'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["es"]={"g-flurpruefung":["¿Qué incluye una inspección visual y funcional antes de comenzar a trabajar?","Antes de la primera misión del día.","Verifique únicamente el nivel de combustible y el color del vehículo.","Compruebe los frenos, la dirección, las horquillas, los neumáticos y los dispositivos de seguridad según las instrucciones de funcionamiento.","Realice una prueba de conducción con la carga elevada.","La inspección diaria incluye las piezas y funciones relevantes para la seguridad según las instrucciones de funcionamiento."],"g-rueckhalt":["¿Cómo se aborda el actual sistema de retención del conductor?","La carretilla elevadora dispone de un sistema de retención obligatorio.","Úselo correctamente mientras conduce.","Úselo sólo en pisos irregulares.","Desactívelo para trayectos cortos.","Los sistemas de retención previstos deben utilizarse de acuerdo con las instrucciones del fabricante; Proporcionan una protección especial en caso de vuelco."],"g-mangelmelden":["¿Qué se aplica a una carretilla elevadora con la horquilla dañada?","Al comprobarlo se nota un diente claramente doblado.","Si es posible, distribuya la carga al otro diente.","Conduzca únicamente cargas ligeras hasta el próximo servicio.","No utilice la carretilla elevadora e informe del defecto a la persona responsable.","El equipo de manipulación de carga dañado puede fallar; Los defectos relacionados con la seguridad requieren una parada hasta su aclaración."],"g-einweisung":["Cambias a una carretilla elevadora con diferentes controles. ¿Qué se requiere antes de su uso?","El funcionamiento difiere del de su vehículo anterior.","Instrucciones relacionadas con el dispositivo y cumplimiento de las instrucciones de funcionamiento.","Siempre es suficiente una breve explicación de un colega no involucrado.","No hay información adicional si tienes licencia de montacargas.","Una calificación general no reemplaza las instrucciones necesarias sobre el dispositivo realmente utilizado."],"g-anbaugeraet":["Deberías utilizar un archivo adjunto. ¿Qué revisas primero?","Un nuevo equipo cambia la forma en que se recoge la carga.","Si el implemento se ajusta a la homologación del vehículo y a la carga permitida.","Sólo si el dispositivo se puede fijar visualmente.","Si el archivo adjunto se puede instalar sin documentación.","Los accesorios pueden cambiar la capacidad de carga restante y el centro de carga; Se deben comprobar las homologaciones y la información sobre la capacidad de carga."],"g-diagramm":["¿Por qué necesitas el diagrama de capacidad de carga?","Hay una carga pesada con el centro de gravedad muy hacia afuera.","Para determinar la ruta más corta.","Evaluar la carga máxima permitida en función de la altura de elevación y el centro de carga.","Para determinar la capacidad del tanque.","Las cargas permitidas dependen, entre otras cosas, de la distancia al centro de carga y de la altura de elevación."],"g-lastschwerpunkt":["¿Qué sucede normalmente cuando el centro de gravedad avanza más?","Una carga larga sobresale mucho por delante de las horquillas.","La capacidad de carga permitida puede disminuir.","La capacidad de carga siempre está aumentando.","La distancia no influye en el momento de vuelco.","Una mayor distancia al centro de carga aumenta el momento de vuelco y puede reducir la capacidad de carga permitida."],"g-gabelabstand":["¿Cómo deben las horquillas recoger un palet adecuado?","Quiere recoger un palet cargado uniformemente.","Con las púas lo más cerca posible y sólo en una esquina.","Con una distancia tan grande que el palet se vuelque hacia un lado.","Con una distancia adecuada entre púas y suficiente superficie de soporte y de chasis.","La carga debe apoyarse de forma segura y lo más uniforme posible sobre las horquillas."],"g-schieflast":["Una carga está apilada de forma inestable. ¿Qué es lo correcto?","Las cajas de cartón pueden caerse al levantarlas.","Comience lentamente; la carga se estabiliza sola.","Antes de recoger la carga, asegúrela suficientemente o haga que la vuelvan a montar.","Eleve la carga por encima de la altura de la cabeza para que no estorbe.","La carga suelta o inestable puede caer y poner en peligro a las personas; Lleve a cabo primero las medidas de seguridad."],"g-personen":["¿Se puede levantar a una persona con horquillas normales?","Un colega quiere alcanzar una luz.","Sí, si el compañero lleva casco.","No, las personas sólo pueden utilizar las instalaciones designadas y permitidas de acuerdo con requisitos especiales.","Sí, siempre que se alcance una pequeña altura.","Las bifurcaciones normales no son una plataforma de trabajo personal; El transporte y elevación de personas está sujeto a requisitos especiales."],"g-transporthoehe":["¿Cómo se suele transportar un palet?","El camino está despejado y nivelado.","Con la carga elevada sólo lo necesario y de acuerdo con las instrucciones de funcionamiento.","Con la carga levantada lo más alto posible para que se vea mejor.","Con el mástil de elevación fuertemente inclinado hacia adelante, independientemente de la carga.","Una posición de transporte baja reduce el riesgo de vuelco y colisión; Las instrucciones del dispositivo son decisivas."],"g-kurvenfahrt":["¿Por qué es peligroso tomar curvas rápidamente con una carretilla elevadora?","Quiere salir rápidamente de un camino estrecho.","Porque simplemente agota la batería más rápido.","Porque la carretilla elevadora gira automáticamente mejor.","Porque las fuerzas laterales afectan la estabilidad y pueden provocar vuelcos.","En las curvas entran en juego fuerzas adicionales; la velocidad debe ajustarse a la carga y las condiciones."],"g-ladebruecke":["¿Qué revisas antes de subir a un puente de carga?","Deberías conducir en un camión.","Sólo si el camino parece lo suficientemente ancho.","Capacidad de carga, soporte seguro y protección contra desplazamientos, además de asegurar el vehículo.","Sólo si la iluminación está encendida.","Los puentes de carga y los vehículos deben estar asegurados contra movimientos y ser adecuados para la carga."],"g-fussgaenger":["¿Cómo te comportas en una intersección confusa con los peatones?","Las conexiones visuales están restringidas.","Conduzca a una velocidad adecuada, deténgase si es necesario y garantice una visibilidad segura.","Siempre reclame el derecho de paso cuando transporte una carga.","Simplemente toca la bocina y sigue conduciendo.","Los peatones tienen necesidades especiales de protección; La velocidad, la visibilidad y la comunicación deben adaptarse a la ruta del tráfico."],"g-batterieladen":["¿A qué se debe prestar especial atención al cargar una batería de propulsión?","Se utiliza una estación de carga de baterías.","El lugar de carga se puede seleccionar independientemente de las instrucciones del fabricante.","Se permiten llamas abiertas mientras el camión esté parado.","Zona de carga adecuada, ventilación suficiente y especificaciones del fabricante, así como protección contra incendios y explosiones.","Durante la carga pueden surgir peligros debido a la energía eléctrica, gases y productos químicos; Se deben respetar las medidas de protección previstas."],"h-beauftragt":["¿En qué condiciones se permite operar una plataforma aérea de trabajo de forma independiente?","Se debe utilizar una plataforma de trabajo en la empresa.","Si tienes carnet de conducir de coche.","Si es apto, instruido o cualificado y encargado por el empresario.","Si alguna vez has visto una plataforma de trabajo.","El empleador debe garantizar la idoneidad, las calificaciones y las asignaciones de acuerdo con los requisitos operativos."],"h-vorpruefung":["¿Qué se debe comprobar antes de empezar a trabajar con la plataforma aérea de trabajo?","El escenario estuvo afuera durante la noche.","Prueba visual y funcional según instrucciones del fabricante incluyendo dispositivos de seguridad.","Sólo el color y la edad del escenario.","Si el material de trabajo ya se encuentra en la plataforma.","Antes del uso se deben comprobar la máquina, los controles, las funciones de emergencia y los daños visibles según las instrucciones de funcionamiento."],"h-tragfaehigkeit":["¿Qué información determina la carga permitida en la cesta de trabajo?","A dos personas les gustaría llevar consigo herramientas adicionales.","Las personas son libres de estimar el peso total permitido.","Sólo cuenta el peso de la persona más pesada.","No se debe sobrepasar la capacidad de carga especificada para personas, herramientas y material.","La carga nominal se refiere a la carga total permitida, incluido el material transportado."],"h-untergrund":["¿Qué consideras antes de montar un escenario con soportes?","Está trabajando cerca de un área llena.","Sólo al alcance del boom.","Compruebe la capacidad de carga y la regularidad del subsuelo, así como el soporte adecuado según las instrucciones.","Sobre el menor número posible de soportes extendidos.","Un terreno insuficiente o un soporte inadecuado pueden provocar una pérdida de estabilidad."],"h-wind":["Se levanta un fuerte viento. ¿Cómo se hace?","Te encuentras con un escenario al aire libre.","Observe los límites del fabricante y, si se exceden, detenga la operación o baje la canasta de manera segura.","Extienda la plataforma lo máximo posible para que quede más estable.","Sólo reaccione si caen objetos sueltos.","Las condiciones de viento permitidas por el fabricante son límites de uso; El viento puede crear fuerzas adicionales peligrosas."],"h-strom":["Tienes que trabajar cerca de una línea eléctrica aérea. ¿Qué es crucial?","Hay una línea viva en el área de trabajo.","Un casco sustituye a mantener la distancia de seguridad.","Simplemente aísle la canasta y trabaje sin coordinación.","Aclare la zona de peligro y garantice las distancias de protección necesarias u otras medidas adecuadas.","También es posible una descarga eléctrica sin contacto directo; Las medidas de protección necesarias deben determinarse antes del inicio de la operación."],"h-notablass":["¿Por qué es necesario conocer el procedimiento de descenso de emergencia?","Es posible que se produzca un fallo del control normal.","De modo que, en caso de avería, sea posible un rescate seguro según el dispositivo.","Para que el dispositivo funcione más rápido en funcionamiento normal.","Para reemplazar las pruebas regulares.","Los controles de emergencia, los conceptos de descenso de emergencia y rescate deben conocerse y funcionar antes de su uso."],"h-gelaender":["¿Cómo se consigue altura adicional en la cesta de trabajo?","Un punto de montaje está fuera de su alcance.","Sube a la valla de la cesta.","Coloca una tabla en la barandilla.","Utilice una plataforma adecuada con suficiente altura de trabajo; no subirse a las barandillas.","Subir la valla o elevaciones improvisadas pone en peligro la protección contra caídas."],"h-psaga":["¿Qué requisitos se aplican a los equipos personales de protección contra caídas?","Utiliza una plataforma de trabajo para la que se proporciona un sistema de retención.","Cualquier punto de anclaje fuera de la cesta siempre es suficiente.","Observe la evaluación de riesgos, la información del fabricante y los puntos de anclaje adecuados.","No utilice ningún tipo de seguridad si la cesta tiene barandilla.","La evaluación de riesgos, la construcción del escenario y las instrucciones de funcionamiento determinan si es necesario un EPI y qué EPI."],"h-verfahren":["¿Se puede mover el escenario con la plataforma levantada?","El lugar de trabajo se encuentra a pocos metros.","Sólo si el modelo y las condiciones de funcionamiento lo permiten según las instrucciones del fabricante.","Siempre, mientras todos aguanten.","No, nunca independientemente del diseño y aprobación del fabricante.","El movimiento en posición elevada depende del dispositivo y sólo está permitido dentro de las condiciones de funcionamiento aprobadas."],"h-kollision":["¿Qué hay que organizar cuando se trabaja cerca de grúas u otras máquinas?","Las piezas móviles podrían alcanzar la cesta de trabajo.","Nada; la cesta de trabajo está siempre visible.","Conduzca siempre la cesta de trabajo por encima de las otras máquinas.","Coordinar las áreas de trabajo para evitar colisiones o puntos de pellizco.","El funcionamiento simultáneo de la máquina requiere procesos de trabajo coordinados y protección contra colisiones o atascos."],"h-einstieg":["¿Cómo se entra o sale de la cesta de trabajo?","Llegas a la canasta al nivel del suelo.","Sube por la barandilla exterior.","Por el acceso previsto en una posición segura según las instrucciones de funcionamiento.","A través de una escalera colocada a su lado con la pluma extendida.","Se deben seguir las instrucciones de acceso previstas y del fabricante; Trepar sin control supone riesgo de caída."],"h-defekt":["La función de parada de emergencia no funciona. ¿Qué estás haciendo?","Descubrirá el defecto durante la inspección.","No utilice la plataforma e informe el defecto.","Continúe trabajando si los controles normales funcionan.","Pegue el interruptor con cinta adhesiva para que nadie lo opere.","El fallo de un dispositivo de seguridad es un defecto relevante para la seguridad e impide un funcionamiento seguro."],"h-sicht":["El movimiento de conducción no se puede ver debido a un obstáculo. ¿Cómo lo haces?","Deberías mover un escenario móvil.","Conduzca lentamente sin visibilidad.","Confíe únicamente en el indicador de distancia.","Detenga el movimiento y garantice la visibilidad o instrucciones seguras de acuerdo con las instrucciones de funcionamiento.","Antes del procedimiento se deben inspeccionar de forma segura las personas, los obstáculos y las vías de circulación."],"h-rettung":["¿Qué implica la planificación del despliegue cuando se trabaja a grandes alturas?","El escenario se utiliza en una zona remota.","Sólo la duración prevista del trabajo.","Un concepto de rescate adecuado con personas accesibles y capacitadas y procedimientos de descenso de emergencia.","La suposición de que los bomberos solucionarán cualquier problema de inmediato.","Es necesario organizar de antemano un rescate eficaz, incluso si fallan los controles normales."],"k-befaehigung":["¿Qué se requiere para operar una grúa de forma independiente?","Un nuevo empleado se hará cargo del trabajo de la grúa.","Idoneidad y titulación requerida, instrucción y cometido correspondiente.","Un permiso de conducir es suficiente.","Verlo una vez es suficiente.","Los trabajos de grúa sólo podrán ser confiados a personas calificadas y autorizadas; La instrucción del equipo es parte de ello."],"k-funktionspruefung":["¿Qué se necesita para revisar la grúa antes del inicio del turno?","Te haces cargo de una grúa interior.","Simplemente lea el tiempo de ejecución en la placa de identificación.","Compruebe las funciones relevantes para la seguridad y los defectos visibles según las instrucciones de funcionamiento.","Pruebe la grúa con carga máxima sin comprobar.","El control operativo obligatorio sirve para identificar defectos peligrosos en una fase temprana."],"k-traglast":["¿Cuál es el significado de la capacidad de carga permitida?","Se va a levantar una carga.","Es una recomendación no vinculante.","Sólo se aplica cuando el gancho está completamente retraído.","No se debe exceder la capacidad de carga permitida para el estado de funcionamiento respectivo.","Las cargas permitidas para ciertos tipos de grúas pueden depender del radio, la posición de la pluma y el armamento."],"k-personen":["¿Qué se aplica a las personas bajo cargas suspendidas?","La carga se mueve sobre un área de trabajo.","La zona de peligro debe mantenerse despejada; nadie puede pasar debajo de la carga suspendida.","Un casco le permite permanecer directamente debajo de él.","Se permiten cruces cortos si la grúa se mueve lentamente.","Las cargas suspendidas presentan riesgo de caída y aplastamiento; Se debe mantener a las personas fuera de la zona de peligro."],"k-signale":["No puedes ver al atacante y recibes señales contradictorias. ¿Qué estás haciendo?","La comunicación no es clara.","Continúe con el último comando de conducción.","Detener el movimiento y aclarar claramente la comunicación.","Deposite la carga más rápido y sin consultar.","Los movimientos de carga seguros requieren señales claras y una comunicación clara."],"k-sicht":["¿Quién prestará apoyo durante el transporte si el operador de la grúa no puede ver completamente el recorrido de la carga?","Un pilar del pasillo oscurece el camino.","Persona que pasa por allí sin acuerdo previo.","Nadie; Sólo el gancho es importante.","Una persona adecuada, instruida y con conocimientos claramente acordados.","Si la ruta de carga no es visible, se requieren instrucciones adecuadas u otra solución segura."],"k-ruck":["¿Por qué se deben evitar los movimientos bruscos de la grúa?","Una carga pesada comienza a balancearse.","Crean tensiones dinámicas adicionales y pueden desestabilizar la carga.","Básicamente reducen cualquier movimiento pendular.","Siempre aumentan la capacidad de carga nominal.","Las fuerzas de aceleración y frenado aumentan la tensión sobre la grúa y las eslingas."],"k-sperrbereich":["¿Qué debes comprobar antes de balancear una carga en un área compartida?","Otros empleados trabajan cerca.","Si la carga coincide visualmente con la grúa.","Si la zona de peligro está asegurada y no hay personas en peligro.","Si la carga se puede llevar lo más alto posible por encima de todos.","Las vías de giro y de carga deben estar libres de personas desprotegidas."],"k-stuetzen":["¿Qué es crucial para una grúa móvil con estabilizadores?","Se instala una grúa sobre un terreno parcialmente lleno.","Sólo el ancho del camino.","El color de las placas de soporte.","Base portante así como soporte y distribución de carga según instrucciones de instalación y fabricante.","La instalación tiene una influencia significativa en la estabilidad, especialmente en condiciones cambiantes del terreno."],"k-wetter":["Una ráfaga de viento hace que la carga se balancee significativamente. ¿Qué es lo correcto?","Trabajas al aire libre.","Detenga el movimiento de forma segura y observe las condiciones de funcionamiento permitidas.","Acelere rápidamente el movimiento.","Continúe levantando la carga a pesar de exceder los límites del fabricante.","El viento y los movimientos oscilantes pueden desestabilizar la carga y la grúa; Se deben respetar los límites de aplicación."],"k-freileitung":["¿Qué se aplica cuando se utilizan grúas cerca de líneas eléctricas aéreas?","La pluma o la carga podrían acercarse a la línea.","Con una carga no conductora, las holguras no son importantes.","Aclarar la zona de peligro y las medidas de protección necesarias con los responsables antes de iniciar los trabajos.","Confíe únicamente en la propia reacción del operador de la grúa.","Existen peligros por contacto y descargas eléctricas; Se requieren distancias de protección seguras u otras medidas."],"k-sichern":["¿Qué haces antes de dejar la grúa?","El trabajo está interrumpido.","Deje la carga suspendida.","Deje la grúa desatendida con el motor en marcha.","Baje la carga de forma segura y asegure la grúa según las instrucciones de funcionamiento.","Las cargas suspendidas no deben dejarse sin control; La grúa y la carga deben estar estacionadas de forma segura."],"k-lastanschlag":["¿Cómo saber si el cabestrillo utilizado es el adecuado?","La carga debe levantarse mediante una correa de elevación.","En cuanto a marcado, capacidad de carga, estado e idoneidad para el tipo de accesorio.","Sólo por el color de la correa de elevación.","Porque ya se usó ayer.","La capacidad de carga y el estado deben ser suficientes, teniendo en cuenta las condiciones de montaje."],"k-stopp":["Una persona entra inesperadamente en el camino de carga. ¿Qué estás haciendo?","Actualmente la grúa está moviendo una carga.","Detenga inmediatamente el movimiento de forma segura y despeje la zona de peligro.","Simplemente dé una señal de advertencia y siga conduciendo.","Eleve la carga más y pase sobre ella.","Se debe proteger a las personas de los movimientos de carga; Si existe un peligro inmediato, se debe detener el movimiento."],"k-neuerkran":["Recibirás una grúa con un control desconocido. ¿Qué es lo correcto?","Los controles son diferentes que antes.","Pruebe las claves habituales si sospecha.","Permita que otra persona sin capacitación conduzca adelante.","Reciba las instrucciones necesarias relacionadas con el dispositivo antes de su uso independiente.","Incluso los operadores de grúas experimentados necesitan conocer los controles específicos utilizados, los dispositivos de protección y los límites."],"a-kennzeichnung":["¿Cómo se sabe la capacidad de carga permitida de una eslinga?","Quieres elegir un cabestrillo.","El olor del material.","Sobre la marca de capacidad de carga adecuada y legible y sobre los datos del fabricante.","Sobre el tiempo de almacenamiento.","La capacidad de carga permitida está determinada por el etiquetado y las condiciones de funcionamiento."],"a-sichtpruefung":["Observa un corte claro en la correa de elevación. ¿Cómo lo haces?","Se supone que la banda lleva una carga.","No utilice la cinta y envíela para prueba o rechazo.","Cubre el corte con cinta adhesiva.","Utilícelo únicamente para cargas especialmente ligeras.","Las eslingas textiles dañadas pueden fallar y deben evaluarse según los criterios de descarte."],"a-neigungswinkel":["¿Qué pasa si el ángulo de inclinación de los hilos de la eslinga es mayor que la vertical?","Una percha de dos hilos se extiende más.","Las fuerzas de las hebras siempre disminuyen.","Las fuerzas de las hebras siguen siendo las mismas.","Las fuerzas en los hilos aumentan; Se deben respetar los ángulos y capacidades de carga permitidos.","A medida que aumenta la extensión, aumenta la fuerza de tracción por hilo de soporte."],"a-schwerpunkt":["¿Por qué necesitas saber el centro de gravedad de la carga?","La carga se acumula de manera desigual.","Para que la carga se mantenga estable al levantarla y no vuelque incontrolablemente.","Para seleccionar el color de las eslingas.","Para que la carga pueda girar más rápido.","Los puntos de fijación desfavorables o la posición del centro de gravedad pueden provocar vuelcos, resbalones o pendientes inclinadas."],"a-kantenschutz":["Una correa de elevación se apoya contra el borde afilado del componente. ¿Qué se debe hacer?","Se debe levantar el componente.","Levante la carga rápidamente antes de que se dañe la correa.","Utilice una protección de bordes adecuada y compruebe el tipo de fijación.","Limpie la superficie de carga únicamente con un paño.","Los bordes afilados pueden dañar las fibras de soporte; el equipo de eslingado debe protegerse en consecuencia."],"a-haken":["¿A qué le prestas atención cuando colocas un cabestrillo?","Usas un gancho de carga.","Coloque el cabestrillo en el costado de la punta del gancho.","Mantenga la trampilla de seguridad abierta permanentemente.","Cargue el gancho según lo previsto en la base del gancho y observe los dispositivos de seguridad.","Una carga inadmisible en la punta del gancho y una falta de sujeción pueden provocar que se desenganche."],"a-knoten":["¿Se puede acortar una correa de elevación que sea demasiado larga con un nudo?","La longitud del tope no encaja.","No; Utilice únicamente un tipo de eslinga adecuado y aprobado o un equipo de eslinga adecuado.","Sí, si el nudo está muy apretado.","Sí, siempre y cuando la carga esté actualmente parada.","Los nudos pueden debilitar significativamente las eslingas textiles y no se permiten ajustes de longitud improvisados."],"a-probehub":["¿Por qué al principio se levanta una carga con cuidado?","Quiere transportar con seguridad.","Para que pueda viajar lo más rápido posible.","Comprobar la posición de las eslingas, estabilidad y centro de gravedad.","Porque la capacidad de carga aumenta automáticamente.","Una primera carrera controlada ayuda a detectar paradas incorrectas y posiciones de carga inestables."],"a-lastweg":["¿Dónde se permite permanecer a las personas mientras se transporta la carga?","La carga se mueve con una grúa.","Directamente debajo de la carga con casco protector.","Sobre la carga si pueden aguantar.","Fuera de la zona de peligro y no debajo de cargas suspendidas.","Incluso si se fija con cuidado, todavía existe peligro de que las cargas se caigan o se balanceen."],"a-haende":["¿Cómo se evitan las lesiones por aplastamiento al destetar?","La carga se acerca a la superficie de apoyo.","Mantenga las manos y los pies fuera del área de aplastamiento y utilice ayudas adecuadas.","Sostenga la carga con la mano desnuda.","Colóquese entre la carga y la pared para corregir la posición.","Entre la carga y el soporte surgen puntos de pellizco peligrosos."],"a-vierstraenge":["¿Qué se aplica a la distribución de la carga en una suspensión de cuatro patas sin compensación de carga?","Se adjunta una carga rígida.","Los cuatro hilos inevitablemente llevan la misma cantidad.","Sin prueba de una distribución uniforme, la capacidad de carga no se puede utilizar como estimación general para cuatro cordones igualmente cargados.","El ángulo de inclinación es entonces irrelevante.","La carga desigual de los hilos es posible con cargas rígidas; Esto debe tenerse en cuenta en el diseño y en la capacidad de carga admisible."],"a-chemikalien":["¿Qué se aplica al utilizar eslingas textiles en contacto con productos químicos?","Estás trabajando con un líquido desconocido.","El color de la correa muestra de forma fiable su durabilidad.","Cada banda textil es resistente a todos los productos químicos.","Verifique la durabilidad y la información del fabricante; No utilice medios inadecuados.","Los productos químicos pueden atacar las eslingas y reducir imperceptiblemente su capacidad de carga."],"a-aufbewahrung":["¿Cómo se guardan las eslingas después de su uso?","La misión ha terminado.","Limpio, seco y protegido de daños según especificaciones del fabricante.","Atascado en el suelo bajo una carga desprotegida.","En cualquier gancho exterior afilado.","Un almacenamiento adecuado evita el desgaste prematuro y facilita la inspección visual."],"a-auswahl":["¿A qué se debe prestar especial atención cuando se trabaja con cargas sensibles o con bordes afilados?","Se debe mover un componente pintado de la máquina.","Sólo la velocidad de transporte.","Eslingas adecuadas y medidas de protección de la superficie de carga y bordes.","Independientemente de la carga, siempre el mismo cable de acero.","El tipo de accesorio y el material deben coincidir con la geometría, la superficie y el peligro."],"a-abstimmung":["El operador de la grúa no le ve. ¿Cómo das instrucciones?","Estás asignado como atacante.","Saludas a voluntad hasta que comienza un movimiento.","Sólo haces una llamada y te marchas.","A través de señales claramente acordadas u otra comunicación confiable.","Los atacantes y operadores de grúas deben comunicarse claramente; Si no está claro, se debe detener el movimiento."],"b-qualifikation":["¿Qué necesita una persona para operar de forma segura una excavadora hidráulica durante la operación?","Una nueva persona debería hacerse cargo de los trabajos de construcción.","Calificaciones apropiadas, instrucción relacionada con el dispositivo y tarea requerida.","Sólo un permiso de conducir de coche.","Sólo una rápida observación de la operación.","El empresario debe garantizar las cualificaciones necesarias e instruir al operador de forma adecuada para la tarea."],"b-pruefung":["¿Qué se incluye en la inspección diaria de la máquina?","Te haces cargo de una excavadora.","Compruebe el color de la pintura y la tapicería de los asientos.","Inspección visual y pruebas funcionales según las instrucciones de funcionamiento, por ejemplo para detectar fugas y daños.","Mueva el brazo a toda velocidad hasta que se detenga.","Los daños en el sistema hidráulico, el chasis y los dispositivos de seguridad pueden provocar accidentes graves."],"b-leitungen":["¿Qué se debe saber sobre las tuberías subterráneas antes de excavar?","Deberías cavar una zanja.","Sólo la profundidad aproximada del pozo de excavación planificado.","El color de las marcas sobre el suelo es suficiente.","Aclarar la ubicación de posibles líneas y determinar las medidas adecuadas de seguridad y exploración.","Las tuberías de electricidad, gas o agua pueden tener consecuencias mortales si se dañan."],"b-schwenkbereich":["¿Cómo se protege a las personas en el área de giro de la excavadora?","El material se recoge con la pluma.","Acordone o asegure la zona de peligro y mantenga alejada a las personas.","Antes de girar, mueva la pala lentamente.","Conduzca sobre el área sobre las cabezas.","La superestructura giratoria y los equipos de trabajo crean riesgos de aplastamiento e impacto."],"b-boeschung":["¿Qué es importante cuando se trabaja cerca del borde de un pozo de excavación?","La excavadora se encuentra sobre un terreno firme o relleno.","Sólo la profundidad de excavación determina la colocación permitida.","Preste atención a la capacidad de carga y fijación del borde, así como a las distancias requeridas según la evaluación de riesgos.","Conduce lo más cerca posible del borde para ahorrar alcance.","Si no hay suficiente espacio libre o terreno estable, el terraplén puede fallar y la máquina puede caer."],"b-standsicherheit":["¿Por qué la pendiente y el terreno son cruciales para su uso?","El sitio de construcción está en una pendiente.","La máquina es igualmente estable en cualquier superficie.","Los trenes de rodaje sobre orugas eliminan cualquier riesgo de vuelco.","Los desniveles y las pendientes pueden afectar la estabilidad; Respete los límites de aplicación.","La estabilidad y la seguridad contra vuelcos dependen del suelo, el equipo, la carga y la posición de la máquina."],"b-wechselgeraet":["¿Qué se comprueba después de cambiar el cucharón de una excavadora mediante un enganche rápido?","Se instaló un nuevo archivo adjunto.","Si está correctamente bloqueado y asegurado según las instrucciones de funcionamiento.","Sólo si el color de la pala coincide.","Si el sistema hidráulico funciona lo más silenciosamente posible.","Los cierres defectuosos pueden provocar la caída de los accesorios."],"b-heben":["¿A qué se debe prestar atención al levantar una carga que cuelga libremente con una excavadora?","La excavadora se utiliza para operaciones de elevación.","Sólo la fuerza de excavación habitual es decisiva.","Observe la carga de elevación permitida, los puntos de fijación adecuados y los dispositivos de protección prescritos.","La carga se puede enganchar a los dientes del cucharón.","La elevación sólo está permitida dentro de las condiciones de funcionamiento previstas y con el equipo adecuado."],"b-rueckwaerts":["Tienes que dar marcha atrás, pero no puedes ver el camino. ¿Qué es lo correcto?","Otros trabajadores están cerca.","Conduzca con precaución y sin visibilidad.","Simplemente toca la bocina y sigue conduciendo.","Deténgase, garantice la visibilidad y la zona de peligro u organice instrucciones adecuadas.","La marcha atrás no debe poner en peligro a las personas; La visibilidad limitada requiere medidas adicionales."],"b-kabel":["El boom podría acercarse a una línea eléctrica aérea. ¿Qué estás haciendo?","Trabaja en un sitio de construcción estrecho.","Aclarar previamente la zona de peligro y las medidas de protección adecuadas con los responsables.","Ignore la línea si la pluma está pintada.","Mueva la pluma sólo con especial rapidez.","Los riesgos eléctricos surgen del contacto y de las descargas eléctricas; Son necesarias distancias de seguridad y medidas de protección."],"b-verlassen":["¿Cómo se estaciona la excavadora antes de partir?","Tómate un descanso.","Deje la barrera flotando libremente.","Deposite de forma segura el equipo de trabajo y asegure la máquina contra movimientos y usos no autorizados.","Deje el motor en marcha y la cabina abierta.","Los equipos de trabajo bajados y la protección contra movimientos involuntarios reducen el riesgo de accidentes."],"b-hydraulik":["Observa aceite hidráulico a alta presión en una línea dañada. ¿Qué es lo correcto?","Hay una fuga en una línea.","Siente la fuga con tu mano.","Coloque una nueva abrazadera bajo presión.","Apague la máquina de forma segura, deje que se reduzca la presión y encargue las reparaciones a personal especializado autorizado.","El fluido hidráulico a alta presión puede provocar lesiones graves; nunca revise si hay fugas a mano."],"b-unterbau":["¿Cuál es el peligro de conducir sobre superficies inestables?","El suelo está blando después de la lluvia.","La máquina puede hundirse, deslizarse o volcarse.","La unidad se ensancha automáticamente.","Esto hace que el rango de giro sea más seguro.","Una capacidad de carga insuficiente puede afectar considerablemente a la estabilidad y a la seguridad en la conducción."],"b-arbeitsgeraet":["¿Alguien puede trabajar debajo de un implemento elevado?","Una persona quiere controlar algo debajo de la pala.","Sí, cuando el motor está al ralentí.","No, no sin el soporte seguro y la sujeción necesarios del equipo de trabajo.","Sí, si la persona lleva casco de seguridad.","El equipo hidráulico puede hundirse; Los trabajos de mantenimiento requieren equipos de trabajo seguros."],"b-geraeteart":["Se pasa de una excavadora hidráulica a una cargadora de ruedas. ¿Qué se requiere?","El comportamiento de operación y movimiento es diferente.","El mismo calzado.","Una prueba de manejo sin instrucciones.","La cualificación o instrucción requerida para el nuevo tipo de máquina.","La cualificación debe coincidir con el tipo de máquina utilizada y los requisitos operativos específicos."],"g-neigung":["Usted está conduciendo un montacargas cargado en una pendiente. ¿Qué es importante?","El recorrido tiene una clara pendiente.","Guíe siempre la carga cuesta abajo, incluso si es pesada.","Guíe la carga cuesta arriba y observe las pautas operativas para conducir en pendientes.","Independientemente del sentido de la marcha, levante la horquilla al máximo.","En subidas y bajadas, la carga debe transportarse siempre cuesta arriba; Deben observarse el vehículo y las instrucciones de funcionamiento."],"g-gabelabsenken":["¿Por qué hay que bajar la horquilla al aparcar?","La carretilla elevadora está estacionada para un descanso.","Para que otros puedan usar el tenedor para subir.","Para que la bifurcación sea más visible desde lejos.","Para que levantar la carga no suponga un riesgo innecesario de tropiezo o lesión.","Los dispositivos de manipulación de cargas bajados reducen el riesgo de accidentes debido a horquillas que sobresalen o no están aseguradas."],"g-fahrerwechsel":["Un colega quiere que le prestemos la carretilla elevadora. ¿Qué debe estar presente?","El colega sólo tiene su permiso verbal.","Debe tener las cualificaciones necesarias y un mandato operativo.","Su propia tarea se aplica automáticamente a él también.","Un permiso de conducir para vehículos privados es suficiente para cualquier negocio.","El liderazgo independiente está ligado a la idoneidad personal, la formación, las cualificaciones y la asignación operativa."],"g-ladungssicherung":["Un palé contiene cajas sueltas y apiladas. ¿Qué es lo correcto?","Una caja de cartón puede caerse mientras se conduce.","Asegure la carga contra resbalones y caídas antes del transporte.","En terrenos particularmente irregulares, conduzca únicamente lentamente.","Compense las cajas sueltas con una posición más alta de las horquillas.","La carga debe estar estable y asegurada contra caídas antes de ser transportada con la carretilla industrial."],"g-bodenbelastung":["Frente a ti hay una manta con capacidad de carga limitada. ¿Cómo decides?","El camino discurre por un nivel intermedio.","Sólo preste atención al peso del camión sin carga.","Aclarar la carga en piso permitida para montacargas y cargas.","Conduzca con impulso para que el techo esté bajo carga durante un período de tiempo más corto.","Lo relevante es la carga real total sobre la zona, incluyendo el vehículo, la carga y las influencias dinámicas."],"g-verkehrswege":["Un sendero señalizado se cruza en nuestro camino. ¿Qué es lo correcto?","Los peatones pueden acceder al cruce en cualquier momento.","Siempre puedes reclamar prioridad con la bocina.","Está permitido pasar por encima de las marcas sin ser observado.","Ajuste su velocidad, preste atención a los peatones y continúe conduciendo solo cuando el camino esté despejado.","Las rutas de tráfico deben conducirse teniendo en cuenta a las personas; Las señales de advertencia no reemplazan la visibilidad segura y una ruta despejada."],"g-parkbremse":["Estacionas un montacargas en un terreno nivelado. ¿Qué incluye eso?","Quiere abandonar el asiento del conductor durante varios minutos.","Estacione, aplique el freno de mano y asegúrelo contra el uso no autorizado.","Deje el vehículo únicamente en posición neutra.","Deja el tenedor a la altura de la cabeza para que nadie lo toque.","Antes de partir, el camión debe detenerse de forma segura y asegurarse contra movimientos involuntarios."],"g-typenschild":["¿Qué información es vinculante en lo que respecta a la carga en una carretilla elevadora?","Quieres levantar una máquina pesada.","La capacidad de carga estimada en función del tamaño del vehículo.","La información del fabricante en el diagrama de carga o capacidad de carga.","El peso del último palet transportado.","La carga permitida viene determinada por los datos del fabricante y depende, entre otras cosas, del centro de carga y de la altura de elevación."],"g-tore":["Se llega a un pasaje bajo con una carretilla elevadora. ¿Qué estás comprobando?","Hay una carga enorme sobre el vehículo.","Si el paso con la carga y el accesorio es posible de forma segura.","Sólo la altura del portahorquillas sin carga.","Si puedes pasar más rápido antes de que se cierre la puerta.","Antes de pasar se deben tener en cuenta la altura y la anchura libres, así como las dimensiones de la carga y del vehículo."],"g-reifen":["Durante su revisión diaria encuentra un neumático muy dañado. ¿Qué estás haciendo?","En el neumático se ven daños relevantes para la seguridad.","Conduce despacio hasta su cita de mantenimiento habitual.","Aumentas la presión de los neumáticos y sigues conduciendo.","No pones el vehículo en funcionamiento ni notificas los daños.","Los neumáticos dañados pueden afectar la estabilidad y el manejo; el defecto debe aclararse antes de su uso."],"h-absperren":["Los empleados pasan por debajo de su plataforma de trabajo. ¿Qué es necesario?","Existe peligro por caída de herramientas.","Un área protectora o restringida adecuada debajo del lugar de trabajo.","Sólo un aviso cuando pasas por primera vez.","Guarde las herramientas lo más lejos posible del borde de la canasta.","El área de trabajo debajo de puestos de trabajo elevados debe protegerse contra el peligro de caída de piezas."],"h-werkzeuge":["¿Cómo se transportan las herramientas en la cesta de trabajo?","Se necesitan varias herramientas pequeñas en altura.","Colóquelos sin apretar sobre la barandilla para que estén al alcance de la mano.","Guárdelos y asegúrelos de tal manera que no se caigan ni impidan su funcionamiento.","Colóquelo en el exterior de la barandilla en su bolsillo.","Los objetos sueltos pueden caer y poner en peligro a las personas; Se requiere almacenamiento seguro."],"h-abstuetzung":["Sobre una tapa de alcantarilla hay un soporte. ¿Qué hay que comprobar?","Quieres elevar la plataforma.","Solo asegúrate de que la tapa esté seca.","Si la carga se puede absorber de forma segura en ese punto.","Si no es necesario utilizar los demás soportes.","El subsuelo y las zonas de contacto deben poder absorber de forma segura las fuerzas de apoyo; Las coberturas deberán valorarse por separado."],"h-notaus":["¿Cuándo se debe utilizar el dispositivo de parada de emergencia?","Inmediatamente se produce un movimiento peligroso.","Sólo al final de un turno regular.","Para detenerse en caso de peligro grave según las instrucciones de funcionamiento.","Como sustituto del descenso previsto.","La parada de emergencia se utiliza para evitar peligros, no el control habitual o la parada normal."],"h-schraegstellung":["La advertencia de inclinación del escenario responde. ¿Cómo reaccionas?","La máquina está sobre una superficie inclinada.","Se ignora la advertencia cuando se trabaja a poca altura.","A pesar de la advertencia, conduce hasta la posición de elevación más alta.","Te detienes y llevas el escenario a una condición segura de acuerdo con las instrucciones del fabricante.","Las advertencias de inclinación pueden indicar una estabilidad inadecuada; nuevos movimientos no deben aumentar el peligro."],"h-umgebung":["¿Qué se debe organizar al instalar cerca de una zona de tráfico?","Los vehículos pueden tocar el escenario.","Protección contra colisiones y orientación adecuada del tráfico.","Gire la cesta de trabajo lo más lejos posible sobre la carretera.","Sólo una llamada de advertencia antes de arrancar.","Las plataformas de trabajo aéreas deben estar protegidas contra colisiones con los usuarios de la vía; la instalación debe asegurarse en consecuencia."],"h-ueberlast":["Se activa el aviso de sobrecarga en la cesta. ¿Qué estás haciendo?","Se invitaron herramientas adicionales.","Termine el trabajo a mayor velocidad.","Establezca la carga permitida de la cesta y siga las instrucciones del fabricante.","Apague permanentemente la señal de advertencia.","No se debe superar la carga máxima permitida sobre la cesta, incluidas personas y material."],"h-quetschen":["Conduces la cesta bajo un techo. ¿Qué peligro es particularmente importante?","Queda poco espacio encima de la cesta.","Sujeción o aplastamiento entre la cesta y la estructura.","Que el motor consuma más combustible.","Que el sentido de la marcha siempre se invierta automáticamente.","Los espacios reducidos encima o al lado de la cesta de trabajo pueden provocar lesiones graves por aplastamiento."],"h-stromausfall":["El escenario permanece a gran altura sin un camino principal. ¿Qué es lo correcto?","El control normal de la cesta ya no responde.","Bajas por la barrera sin seguridad.","Esperas hasta el final de tu turno sin ser informado.","Inicie el rescate preparado utilizando personas capacitadas y descenso de emergencia.","Se debe planificar un rescate seguro en caso de perturbaciones; Las personas capacitadas deben conocer las funciones de emergencia."],"h-transportstellung":["¿Cómo se prepara el escenario para un transporte?","La plataforma elevadora se carga en un vehículo adecuado.","Coloque el brazo y la plataforma en posición de transporte según las instrucciones de funcionamiento.","Ate la plataforma lo más lejos posible.","Deje los soportes extendidos para que ocupe más espacio.","La posición de transporte prescrita y la sujeción de la carga dependen del fabricante y de las especificaciones de transporte."],"k-bremsprobe":["¿Qué muestra una prueba funcional del freno de la grúa antes de su uso?","Quiere poder sostener una carga de forma segura.","Si el freno detiene y mantiene el movimiento según lo previsto.","Sólo si funciona la iluminación de la cabina.","Si el gancho puede sostener automáticamente una carga.","Antes del uso se deben comprobar las funciones relevantes para la seguridad según las especificaciones."],"k-schraegzug":["¿Se puede arrastrar una carga lateral en ángulo con la grúa?","El gancho no está verticalmente por encima de la carga.","Sí, si la grúa todavía tiene reserva de carga.","No, las cargas no se deben tirar con tracción diagonal no permitida.","Sí, si las eslingas son especialmente cortas.","La tracción diagonal puede provocar movimientos incontrolados y tensión adicional en la grúa y las eslingas."],"k-verhakt":["Una carga cuelga de la subestructura. ¿Qué es lo correcto?","Se siente resistencia al levantar.","Sigues levantando hasta que se desprenda.","Mueves la carga hacia los lados con sacudidas.","Usted se detiene y retira de forma segura la fijación o el bloqueo.","Las cargas atascadas no deben soltarse con fuerza, ya que pueden surgir fuerzas inaceptables."],"k-anzuheben":["¿Qué compruebas cuando levantas brevemente una carga suspendida por primera vez?","La carga se eleva unos centímetros del suelo.","Si cuelga en equilibrio y el tope es seguro.","Si una persona puede ponerse directamente debajo de la carga.","Si la grúa se vuelve más estable al girar rápidamente.","Se utiliza una elevación controlada breve para comprobar el acoplamiento, el equilibrio y el comportamiento seguro de la carga."],"k-lastweg":["¿Dónde debe estar la ruta de transporte de una carga de grúa?","Varios lugares de trabajo se encuentran bajo la posible trayectoria de carga.","Si es posible, encima de las estaciones de trabajo ocupadas.","Por un camino planificado, despejado y sin personas en riesgo.","Siempre en diagonal por la zona más transitada.","Los recorridos de carga deben organizarse de forma que las cargas suspendidas no pongan en peligro a las personas."],"k-signalverlust":["Se interrumpe la conexión por radio con el mariscal. ¿Qué estás haciendo?","No puede ver la ruta de carga en sí.","Continúas el movimiento lentamente.","Te balanceas experimentalmente en la dirección anterior.","Detienes el movimiento hasta que haya una comprensión clara y segura.","Si hay falta de comunicación, es posible que no continúe el movimiento confuso de la carga."],"k-haken":["El gancho de seguridad no cierra con seguridad. ¿Qué es lo correcto?","Durante la inspección se constata un cierre defectuoso.","El error debe corregirse profesionalmente antes de su uso posterior.","Atas el cierre con fuerza con una brida.","Sólo utiliza el gancho para cargas ligeras.","Los dispositivos de sujeción defectuosos en los ganchos de carga pueden provocar que las eslingas se desenganchen y deben solucionarse."],"k-zugrichtung":["¿Qué es importante para el soporte vertical de una carga?","La carga debe levantarse de una máquina.","El gancho de la grúa debe estar alineado por encima del centro de gravedad de la carga.","El gancho debe colocarse lo más lateralmente posible.","La carga debe ser empujada antes de levantarla.","Una acción de fuerza lo más vertical posible por encima del centro de carga evita fuerzas laterales inadmisibles y oscilaciones incontroladas."],"k-wartung":["Se escucha un chirrido inusual en la grúa. ¿Cómo lo haces?","El ruido se produce al levantar.","Cubre el ruido a través de una mayor velocidad.","Detener las operaciones de forma segura, informar defectos y aclararlos.","Continuar trabajando sin previo aviso hasta el descanso.","Los cambios notables pueden indicar daños relevantes para la seguridad y requerir una inspección."],"k-absetzen":["¿Qué se debe garantizar al bajar la carga de una grúa?","Se coloca una carga pesada sobre una superficie.","La carga puede quedar suelta sobre una superficie inclinada.","Las eslingas se retiran mientras aún está flotando.","La carga es estable y está asegurada contra vuelcos o desplazamientos.","La carga sólo podrá soltarse del dispositivo de eslinga una vez que se haya depositado de forma segura y se haya establecido la estabilidad."],"l-schwerpunkt":["¿Por qué es necesario conocer el centro de gravedad antes de golpear?","Se va a transportar una máquina de forma asimétrica.","Para que la carga quede lo más equilibrada posible al levantarla.","Para que las eslingas se puedan elegir tan largas como se desee.","De modo que la capacidad de carga permitida no influye.","La posición del centro de gravedad influye en la distribución de la carga y en el equilibrio seguro al levantar."],"l-etikett":["Una correa de elevación no tiene una etiqueta de capacidad de carga legible. ¿Qué es lo correcto?","La marca se ha vuelto irreconocible.","Estima la capacidad de carga según el color.","No utilice la correa de elevación hasta que se haya demostrado claramente su idoneidad.","Utilice el cinturón sólo una vez para cargas pequeñas.","Se requieren marcas adecuadas para las eslingas; La capacidad de carga inexplicable impide una selección segura."],"l-kantenschutz":["Sobre un borde de acero afilado hay una banda textil. ¿Qué es necesario?","La carga tiene bordes afilados.","Tira de la banda lo más fuerte posible sin protección.","Realiza el trazo más rápido.","Utilice protección de bordes adecuada u otro equipo de eslinga adecuado.","Los bordes afilados pueden dañar o cortar las eslingas textiles; se requiere una protección adecuada."],"l-spreizwinkel":["¿Cómo afecta un mayor ángulo de inclinación a la carga sobre las eslingas?","Se levanta una carga mediante dos cuerdas inclinadas.","En ángulos menos favorables, las fuerzas en los cordones pueden aumentar.","Las fuerzas del hilo desaparecen.","El ángulo no influye en la tensión.","Con un ángulo de tope menos favorable, las fuerzas por cordón pueden aumentar; Se deben observar las tablas de capacidad de carga."],"l-knoten":["¿Se puede acortar una cuerda de eslinga como se desee mediante un nudo?","La cuerda es demasiado larga para la carga prevista.","Sí, un nudo apretado mejora la capacidad de carga.","No, utilice únicamente métodos de acortamiento y anclaje aprobados.","Sí, si el nudo se asegura con cinta adhesiva.","Los nudos no permitidos debilitan las eslingas y modifican su capacidad de carga permitida."],"l-zeichen":["¿Qué se aplica a la comunicación con la persona que opera la grúa?","La ruta de carga está parcialmente oscurecida.","Varias personas dan señales diferentes al mismo tiempo.","Se utilizan señales claras y previamente acordadas.","Nunca se requiere comunicación con grúas de radio.","Señales claras y responsabilidades claras evitan movimientos incorrectos peligrosos."],"l-sichtpruefung":["¿Cuándo se deben revisar las eslingas para detectar defectos visibles?","Quieres usar una cadena de eslinga.","Antes de su uso, preste atención a cualquier daño visible desde el exterior.","Sólo si ya ha ocurrido un accidente.","Sólo una vez cuando se compra por primera vez.","Antes de cada uso, se deben evaluar las condiciones seguras de trabajo; Los daños visibles impiden un uso seguro."],"l-drehung":["Una carga elevada comienza a girar incontrolablemente. ¿Qué estás haciendo?","La carga se mueve en la trayectoria de carga.","Pones tu mano entre la carga y la pared.","Te colocas bajo la carga y te aferras a ella.","Mantienes la distancia y dejas que el movimiento se detenga de forma controlada.","Los movimientos incontrolados de carga crean riesgos de aplastamiento e impacto; Las personas deben abandonar la zona de peligro."],"l-ablegen":["¿Cuándo se pueden quitar las eslingas de la carga?","La carga se coloca sobre caballetes.","Si la carga es estable y está asegurada contra vuelcos o desplazamientos.","En cuanto toque el suelo por primera vez, independientemente de su posición.","Mientras sigue flotando para ahorrar tiempo.","Las eslingas sólo se podrán retirar una vez colocadas de forma segura y estable."],"l-ketten":["Una eslinga de cadena tiene un eslabón muy doblado. ¿Qué estás haciendo?","El daño es visible incluso antes de levantarlo.","Envuelva el área dañada con alambre.","Retire la cadena del uso y haga que la revise un profesional.","Eleve la carga sólo a la mitad.","Los eslabones deformados de la cadena son daños visibles que pueden impedir un uso seguro."],"b-einweiser":["¿Qué es importante cuando la visibilidad desde la excavadora es limitada?","Una parte del edificio oscurece la zona de conducción.","Medidas o instrucciones visuales apropiadas y comunicación clara.","Sólo mira el capó.","Conduce por la zona de giro a pesar de ser invisible.","Si la visibilidad está restringida, los peligros deben evitarse mediante medidas organizativas y técnicas adicionales."],"b-aushub":["¿Dónde se puede almacenar el material excavado cerca de un pozo de construcción?","El borde de la fosa no debe correr ningún riesgo adicional.","Apílelos directamente en el borde para que los caminos de entrada permanezcan despejados.","Almacenar a una distancia suficientemente segura y según las especificaciones de la obra.","Colóquelo sobre apuntalamiento suelto sin realizar más pruebas.","El material excavado puede poner en peligro los terraplenes y apuntalamientos debido a cargas adicionales; Se deben mantener las distancias de seguridad."],"b-personen":["¿Se permite que las personas permanezcan en el área de giro mientras la excavadora está en movimiento?","Una persona quiere medir mientras realiza una panorámica.","Sí, siempre y cuando lleve casco de seguridad.","Sí, si la excavadora gira lentamente.","No, la zona de peligro debe estar despejada antes del movimiento.","En la zona de giro existe peligro de sufrir lesiones graves por aplastamiento o impacto; la zona debe mantenerse despejada."],"b-ladung":["¿Cómo se transporta material de forma segura con una cargadora de ruedas?","Se debe atravesar el jardín con una pala llena.","Con una posición de transporte baja adecuada y un camino despejado.","Con pala elevada para una mejor visibilidad.","Con puertas abiertas y fuerte ángulo de dirección.","Una posición de transporte adecuada reduce el riesgo de vuelco y mejora la estabilidad de conducción."],"b-anbaupruefung":["¿Qué se comprueba después de acoplar un accesorio?","Se adjuntó una pala nueva.","Sólo la limpieza de la pintura.","El bloqueo seguro y el funcionamiento según las instrucciones de funcionamiento.","Sólo si el dispositivo tiene el mismo aspecto desde fuera.","Un bloqueo incorrecto de los acoplamientos rápidos puede provocar que los implementos se suelten involuntariamente."],"b-einstieg":["¿Cómo se puede subir de forma segura a la cabina de la excavadora?","Los escalones están sucios después de la lluvia.","Sube a la cabina por el brazo.","Súbete a las orugas de un solo salto.","Utilice los escalones y asideros designados y limpie los escalones sucios.","Las subidas adecuadas y los puntos de sujeción seguros reducen el riesgo de resbalones y caídas."],"b-graben":["La pared de una trinchera muestra grietas y se está desmoronando. ¿Qué es lo correcto?","Trabajas justo al lado de la zanja.","Detener el trabajo y hacer que los responsables aseguren el pozo de excavación.","Simplemente conduzca más cerca del borde para cerrar la zanja.","Profundice aún más la zanja sin protección.","Las grietas y los movimientos del suelo pueden indicar inestabilidad y requerir una evaluación de seguridad adicional."],"b-betanken":["¿A qué se presta atención al repostar una máquina de movimiento de tierras?","El tanque está casi vacío.","Asegure el motor y las fuentes de ignición según las instrucciones del fabricante y evite derrames.","Rellene siempre gasolina o diésel en la cabina.","Fume mientras reposta combustible cuando no hay viento.","Los riesgos de incendio y ambientales al manipular combustible requieren medidas de protección adecuadas."],"b-laufwerk":["¿Por qué es necesario revisar periódicamente las orugas y el tren de aterrizaje?","Nota vibraciones inusuales mientras conduce.","Para que la máquina pueda moverse más rápido.","Porque los daños pueden afectar a la conducción segura y a la estabilidad.","Porque siempre está permitido trabajar sin inspección visual.","Los daños a la unidad pueden afectar la maniobrabilidad, la estabilidad y la operación segura."],"b-einweisen":["¿Qué se requiere cuando se trabaja cerca del tráfico público de peatones?","Una excavadora trabaja directamente en el borde de una acera.","Los peatones deben circular por la zona de columpios por sí mismos.","Simplemente pegue un cartel en la pala.","Acordone eficazmente la zona de peligro y dirija el tráfico de forma segura.","Terceros no deben entrar en la zona de peligro de las máquinas de movimiento de tierras; Son necesarias barreras y rutas de tráfico adecuadas."],"g2-fahrweg":["Hay líquido derramado en el camino. ¿Cómo lo haces?","La carretilla elevadora pasaría directamente sobre la zona resbaladiza.","Deje de conducir y haga asegurar o retirar el punto de peligro.","Pase por el lugar lo más rápido posible con la horquilla levantada.","Espero neumáticos más secos y seguir conduciendo sin cambios.","Las vías contaminadas ponen en peligro la estabilidad y deben asegurarse adecuadamente antes de circular por ellas."],"g2-sichtladung":["Un palé alto bloquea la vista hacia adelante. ¿Qué es lo correcto?","Tienes que conducir hasta un área de almacenamiento y no puedes ver la ruta.","Levante el palé hasta que pueda ver debajo.","Conduzca únicamente utilizando métodos adecuados y seguros, como dar marcha atrás con una vista clara.","Aún puede conducir por la carretera sin una señal o una vista despejada.","El sentido de la marcha y la visibilidad deben permitir una observación segura de la ruta de circulación; Las cargas no deben reemplazar la inspección visual."],"g2-fussgaengerstop":["Un peatón se detiene justo al lado de la carretilla elevadora. ¿Qué estás haciendo?","La persona se encuentra dentro del posible rango de conducción y giro.","Adelantar al peatón acelerando brevemente.","Pase por delante de la persona que tiene la carga levantada.","Deténgase y continúe conduciendo únicamente a una distancia segura.","Las personas deben mantenerse alejadas de la zona de peligro; Si es necesario, se deberá interrumpir el viaje."],"g2-hubmast":["Observa una línea hidráulica dañada en el mástil de elevación. ¿Qué se aplica?","Hay una fuga visible de aceite hidráulico del implemento.","Poner la carretilla fuera de servicio y comunicar los daños.","Compruebe la fuga manualmente mientras levanta.","Sólo levante cargas más pequeñas hasta que termine el turno.","Los daños hidráulicos pueden provocar movimientos incontrolados; El uso seguro no está garantizado hasta la prueba."],"g2-lagerregal":["Quiere guardar un palé en un estante. ¿Qué revisas primero?","El nivel del estante es alto y se debe mantener la capacidad de carga.","Empuje el palet hacia el estante lo más rápido posible.","Compruebe que el compartimento de los estantes, el peso de la carga y el espacio de almacenamiento libre sean adecuados.","Calcule el peso total basándose únicamente en la cantidad de cajas.","Los estantes y los medios de transporte deben adaptarse a la situación de carga y almacenamiento."],"g2-batterieschaden":["La batería de una carretilla elevadora está dañada externamente. ¿Qué es lo correcto?","Antes de cargar, se notan grietas o líquido inusual.","Cubra los daños con cinta adhesiva y cárguelo inmediatamente.","Deje que otra persona cargue la batería sin comprobarla.","No cargar ni utilizar e informar a los especialistas responsables.","Las baterías dañadas plantean riesgos eléctricos y químicos y requieren una evaluación profesional."],"g2-fahrerkabine":["¿Qué se aplica a los objetos sueltos en la zona del conductor?","Las herramientas están en el piso al lado de los pedales de control.","Retire los objetos y mantenga despejada el área de operación.","Sostenga la herramienta únicamente con un pie mientras conduce.","Oculte las piezas sueltas debajo del asiento del conductor.","Los objetos sueltos pueden bloquear los pedales y perjudicar el funcionamiento seguro del vehículo."],"g2-uebergabe":["Te haces cargo de una carretilla elevadora después de un cambio de turno. ¿Qué incluye eso?","Un colega utilizó el vehículo por última vez.","Supongamos que el colega se ha hecho cargo de todos los controles.","Realice la inspección necesaria y pregunte sobre defectos conocidos.","Inicia el viaje sin mirar la máquina.","La persona que se haga cargo debe asegurarse de que se encuentre en condiciones seguras antes de su uso."],"g2-transportsicherung":["Un objeto alto está suelto sobre el palé. ¿Cómo actúas?","La carga podría inclinarse hacia adelante al frenar.","Lleve la horquilla especialmente alta para que la carga permanezca estable.","Simplemente toma las curvas despacio y sigue derecho más rápido.","Coloque la carga de forma estable y asegúrela contra vuelcos o caídas.","Las cargas sueltas deben estabilizarse antes del transporte para que los movimientos de frenado y conducción no provoquen su caída."],"g2-arbeitsende":["¿Qué es importante con una carretilla elevadora desatendida?","Terminas tu turno y abandonas el área.","Estacione el vehículo de forma segura y asegúrelo contra desplazamientos y uso no autorizado.","Deje la llave puesta para que sus compañeros puedan encontrar la máquina.","Deje el tenedor a la altura de los ojos para que sea visible.","El aparcamiento seguro incluye la manipulación de cargas a baja altura y la protección contra movimientos y puestas en marcha no autorizadas."],"g2-bremsweg":["¿Por qué hay que prestar especial atención a la distancia de frenado bajo carga?","La carretilla elevadora transporta mercancías pesadas a través de un pasillo del almacén.","Frene siempre más tarde con una carga pesada que sin carga.","Ajuste la velocidad a las condiciones de visibilidad, terreno y carga.","Al frenar, levante bruscamente la carga para desacelerar mejor.","La masa y el estado de la carretera influyen en la distancia de frenado; La velocidad adaptada es clave."],"g2-rampe":["¿Qué revisas antes de subir una rampa empinada?","La ruta puede ser demasiado empinada para el vehículo.","Conduzca por la rampa a máxima velocidad independientemente de la pendiente.","Conduzca por el borde de la rampa con la carga levantada.","Compruebe la pendiente permitida y el modo de funcionamiento seguro en las especificaciones del vehículo.","Sólo se podrán utilizar rampas dentro de los límites operativos previstos; Las instrucciones de funcionamiento y el control de carga son decisivos."],"g2-zinke":["Un palet es más ancho que la distancia entre horquillas. ¿Qué hay que tener en cuenta?","Planea asumir una carga inusualmente grande.","Ajuste la distancia de las horquillas y los puntos de montaje para adaptarlos a la carga.","Utilice sólo un diente si la carga es demasiado ancha.","Eleve la carga en ángulo hasta alcanzar la posición correcta.","Una absorción de carga uniforme y adecuada reduce el deslizamiento y el vuelco."],"g2-betriebsanweisung":["¿Qué papel juega la regulación operativa del tráfico?","En el almacén se aplican zonas peatonales y de sentido único marcadas.","En el caso de las carretillas elevadoras sólo se aplican las normas de la vía pública.","Siga las rutas y normas de tráfico especificadas.","Ignore las marcas una vez cargado el vehículo.","Las rutas de la empresa y las normas de seguridad protegen el tráfico de carretillas elevadoras y de personas a pie."],"g2-nothalt":["La dirección reacciona de forma inusual durante la conducción. ¿Qué es lo correcto?","El vehículo ya no se puede controlar como de costumbre.","Conduzca a velocidades más altas para que la dirección responda mejor.","Compense el error con desviaciones de dirección especialmente grandes.","Deténgase en un lugar seguro y haga revisar el vehículo.","Una mala dirección pone en peligro la conducción segura; La máquina no debe seguir funcionando sin control."],"g2-anschlagkette":["Quiere mover una carga que cuelga libremente con una carretilla elevadora. ¿Qué se aplica?","La carga debe colgar de un gancho debajo de las horquillas.","Sólo con un dispositivo homologado y un equipo de transporte de carga adecuado.","Cualquier cadena servirá si la carga no es pesada.","Sujete la cadena directamente entre ambas horquillas.","Las cargas que cuelgan libremente cambian la estabilidad; Se requieren aprobaciones del fabricante e instalaciones adecuadas."],"g2-rollenlast":["Un componente cilíndrico se encuentra suelto sobre un palet. ¿Qué estás haciendo?","La carga puede rodar durante el transporte.","Acérquese al palet de forma especialmente brusca.","Asegure el componente para que no se desplace antes de recoger el palé.","Coloque las púas lo suficientemente altas como para que el componente no sea visible.","Las cargas redondas o rodantes requieren una protección fiable contra cambios de posición."],"g2-pruefplakette":["¿Cómo saber si se puede utilizar la carretilla elevadora?","Hay una pegatina de inspección pegada a la máquina.","Cualquier pegatina sustituye siempre la inspección visual diaria.","La falta de espacio libre se puede subsanar con una conducción cuidadosa.","Además de comprobar el vehículo, se debe tener en cuenta el estado de prueba válido y la aprobación operativa.","Las pruebas recurrentes y los controles operativos diarios cumplen diferentes funciones de seguridad."],"g2-licht":["La iluminación del almacén se apagó de repente. ¿Qué es lo correcto?","Ya no puedes ver con seguridad los obstáculos en el camino.","Deje de conducir hasta que se garantice una visibilidad segura.","Aumente la velocidad de conducción para salir del área oscura.","Continúe conduciendo con las horquillas levantadas sin inspección visual.","No se debe circular por una ruta que no se pueda pasar por alto sin medidas de seguridad eficaces."],"g2-ueberhang":["Una carga se extiende mucho más allá del costado de la horquilla. ¿Qué estás comprobando?","Quiere transportar el palet a través de una puerta estrecha.","Compensa la proyección lateral con una curva rápida.","Evalúe el espacio libre, la estabilidad y la capacidad de carga permitida antes de conducir.","Conducir la carga a máxima velocidad independientemente de su forma.","Los voladizos aumentan el riesgo de colisión y pueden alterar la estabilidad y el espacio de tránsito requerido."],"g2-wartungsbereich":["Hay barreras frente a un área de mantenimiento. ¿Cómo te comportas?","Tu ruta habitual está temporalmente cerrada.","Mueva las barreras brevemente y pase desapercibido.","Conduzca directamente a través del área de trabajo bajo carga.","Observe el cierre y elija una ruta alternativa aprobada.","No se podrá acceder ni atravesar las zonas acordonadas sin autorización."],"g2-bremsprobe":["¿Cuándo tiene sentido realizar una prueba de funcionamiento del freno de servicio?","Preparas la carretilla elevadora antes del trabajo.","Como parte de la inspección requerida antes de su uso.","Realice únicamente después de un accidente grave.","Sólo si el camión ya ha alcanzado alta velocidad.","Antes de su uso se comprueba el funcionamiento de los dispositivos relevantes para la seguridad."],"g2-fahrzeuganhaenger":["Quiere tirar de un remolque con una carretilla elevadora. ¿Qué se requiere?","La empresa está planificando el transporte con carga adjunta.","Ate cada remolque a una horquilla sin comprobarlo.","Tenga en cuenta las indicaciones del fabricante, el acoplamiento adecuado y la carga de tracción admisible.","Simplemente aumente la presión de los neumáticos y conduzca.","El funcionamiento del tren sólo es posible de forma segura dentro de las especificaciones técnicas y con una conexión adecuada."],"g2-rueckfahrt":["¿Qué es importante al dar marcha atrás con la carretilla elevadora?","Hay una zona confusa en el pasillo del almacén.","Mire siempre sólo por el espejo retrovisor, independientemente del entorno.","Conducir sin visibilidad siempre y cuando se haya pulsado una vez la bocina.","Observar con seguridad el recorrido y la zona de personas y, si es necesario, instruirlas.","Dar marcha atrás requiere una visión clara o medidas de seguridad adicionales efectivas."],"g2-lastentnahme":["Sacas un palé de un estante alto. ¿Qué es lo correcto?","Es posible que la paleta no esté centrada.","Recoja la carga de forma segura y estabilícela antes de bajarla.","Deje que la plataforma se balancee hacia un lado mientras la retira.","Revise debajo de la plataforma elevada para ver si está dañada.","La elevación y el descenso controlados evitan la caída de cargas y movimientos peligrosos."],"h2-absenkweg":["¿Por qué la zona debajo de una plataforma aérea de trabajo debe permanecer despejada?","Se baja la cesta y debajo se colocan los materiales.","Presione los materiales hacia abajo con la canasta.","Vigile únicamente la zona de los pies del operador.","Evite el riesgo de aplastamiento y colisión al bajar.","La zona de descenso no debe contener personas ni obstáculos que puedan quedar atrapados."],"h2-transporthoehe":["¿Cómo se mueve un escenario móvil sobre un pasaje bajo?","El espacio libre es menor que el del brazo extendido.","Coloque la plataforma en una posición de transporte adecuada según las instrucciones de funcionamiento.","Deje el brazo extendido y avance bajo el techo.","Presione la canasta contra el costado del marco de la puerta.","Para los movimientos de viaje, la altura total y la posición de transporte deben coincidir con las especificaciones del fabricante y el paso."],"h2-bodenoeffnung":["Hay una abertura no asegurada en el suelo al lado del escenario. ¿Cómo reaccionas?","Cerca de la abertura se sitúa un punto de conducción o de apoyo.","Coloque un soporte directamente en el borde de la abertura.","Cambie el lugar de instalación o haga comprobar la capacidad de carga y la seguridad por parte de un profesional.","Cubra el punto de peligro únicamente con una caja de cartón.","Las aberturas y las zonas de los bordes pueden fallar bajo cargas de apoyo y deben tenerse en cuenta de forma eficaz."],"h2-rettungsperson":["¿Por qué es necesario que una segunda persona esté familiarizada con el procedimiento de rescate?","Un operador podría quedar incapacitado en la cima.","Por lo tanto, el trabajo en la cesta generalmente se puede realizar sin seguridad.","Para que el escenario pueda funcionar más rápido de lo permitido.","Para poder iniciar un rescate seguro en caso de emergencia.","Un concepto de rescate debe tener en cuenta la asistencia terrestre en caso de avería o emergencia."],"h2-werkzeugabwurf":["¿Qué se aplica a las herramientas a gran altura?","Una herramienta suelta podría caer por el borde de la cesta.","Asegure las herramientas para que no pongan en peligro a nadie ni se caigan.","Simplemente coloque herramientas en la barandilla para reducir la carga.","Si es necesario, arroje las herramientas desde la cesta.","La caída de objetos pone en peligro a las personas que se encuentran debajo; El material debe almacenarse de forma segura."],"h2-trittstufe":["Una caja debería servir como espacio adicional para estar de pie en la cesta. ¿Qué es lo correcto?","De lo contrario, apenas llegará al lugar de trabajo.","Coloca la caja en la barandilla y súbete a ella.","No subir a elevaciones improvisadas; Utilice equipo de trabajo adecuado.","Cargue intencionalmente la cesta más allá de la altura permitida.","Las elevaciones improvisadas perjudican la protección contra caídas prevista y no están permitidas."],"h2-lastverteilen":["¿A qué le prestas atención cuando hay varias personas en la cesta de trabajo?","Dos personas trabajan en la cesta con herramientas pesadas.","Juzgue la carga basándose únicamente en el tamaño de la herramienta.","Guarde las herramientas pesadas directamente sobre la barandilla protectora.","No exceda la carga permitida de la cesta, incluidas personas y herramientas.","La capacidad de carga permitida incluye todas las personas, materiales y herramientas en la cesta."],"h2-abstuetzplatte":["¿Cuándo se consideran cuñas adicionales para soportes?","El suelo de instalación sólo puede soportar una carga limitada.","Si esto es necesario para una distribución segura de la carga según las especificaciones.","Para colocar los soportes lo más cerca posible del borde de un foso de construcción.","Para utilizar cualquier autonomía más larga sin información del fabricante.","Para que las fuerzas de apoyo sean seguras se necesitan superficies de contacto suficientes."],"h2-baugrube":["Un escenario debe ubicarse directamente en el borde de un foso de construcción. ¿Qué estás comprobando?","El subsuelo podría ceder lateralmente debido al pozo de excavación.","Extienda los soportes hacia el interior del pozo de excavación.","Asegúrese de que la distancia de seguridad y la capacidad de carga del subsuelo sean suficientes.","Compense el riesgo únicamente levantando la cesta lentamente.","Los pozos de excavación pueden afectar la estabilidad debido a la pendiente y falla del subsuelo."],"h2-witterung":["El glaseado se endurece durante el uso. ¿Cómo actúas?","Las superficies de control y el área de trabajo se vuelven suaves.","Sube el escenario para evitar la nieve y el hielo.","Ignore las advertencias mientras la plataforma esté encendida.","Interrumpa el trabajo y vuelva a evaluar las condiciones de funcionamiento de acuerdo con las instrucciones de funcionamiento.","Los cambios climáticos pueden cambiar la responsabilidad, la operatividad y los límites de uso seguros."],"h2-aufbaukontakt":["Una construcción de acero limita el recorrido de la cesta. ¿Qué es importante?","Al levantarlo existe riesgo de aplastamiento entre la cesta y el transportador.","Planifica los movimientos para que tu cuerpo y tu cesta no queden atrapados.","Haz el recorrido más rápido para que la cesta pase más rápido.","Empuje la construcción con la cesta hacia un lado.","Los puntos de pellizco entre la plataforma y el entorno requieren una observación cuidadosa y un movimiento controlado."],"h2-sicherheitsabstand":["¿Cuándo hay que acordonar la zona de peligro de un escenario?","Una ruta de transporte público pasa por debajo del sitio.","Sólo si ya ha caído un objeto.","Si el movimiento o la caída de objetos pudieran poner en peligro a terceros.","Nunca, ya que la cesta de trabajo básicamente previene todos los peligros.","La zona debajo y al lado del escenario debe estar protegida contra peligros previsibles."],"h2-korbtor":["¿Qué se aplica a la puerta de entrada de la cesta de trabajo?","Ya estás a la altura de trabajo.","Deja la puerta abierta para que puedas salir más rápido.","Ate la puerta permanentemente abierta con una cuerda.","Mantenga la puerta cerrada de acuerdo con el mecanismo de bloqueo provisto.","Los candados suministrados forman parte de las medidas de protección contra caídas de la cesta de trabajo."],"h2-energieleitung":["¿Qué se aplica si una línea aérea no se desconecta de forma segura?","Trabaja con la plataforma aérea cerca de ellos.","Asegúrese de las distancias de seguridad especificadas y las medidas de protección necesarias.","Mueva la canasta justo delante de la línea siempre que no la toque.","Confía en los neumáticos de plástico y trabaja sin huecos.","También son posibles descargas eléctricas sin contacto directo; Se requieren distancias de seguridad."],"h2-schwanken":["La cesta de trabajo empieza a oscilar con una fuerza inusual. ¿Qué es lo correcto?","El movimiento ya no está controlado.","Reajustarse incontrolablemente con contramovimientos rápidos.","Detenga el movimiento y verifique la causa o las condiciones de operación.","Agregue personas adicionales a la canasta para hacerla más pesada.","Una vibración inusual puede indicar condiciones de funcionamiento inadecuadas o un mal funcionamiento."],"h2-ladegeraet":["Un cable de carga de la etapa eléctrica está dañado. ¿Qué estás haciendo?","Al realizar la conexión se ve un aislamiento dañado.","Toque el daño con guantes mojados.","Presione el enchufe en la toma lo más fuerte posible.","No inicie el proceso de carga y haga revisar el cable por un profesional.","El cableado eléctrico dañado supone un riesgo de descarga eléctrica e incendio."],"h2-gelaenderanbau":["¿Puedes quitar una barandilla tú mismo para acercarte?","Un componente impide que las personas se acerquen al lugar de trabajo.","No modifique ni retire los dispositivos de protección por su cuenta.","Después de levantarla, desenrosque la barandilla e instálela más tarde.","Continúe trabajando sin barandilla mientras haya alguien junto a ella.","Los dispositivos de protección estructural no se pueden cambiar sin especificaciones permitidas y medidas de reemplazo seguras."],"h2-lastkran":["¿Se puede utilizar la plataforma como grúa para levantar una carga?","El material debe transportarse colgado libremente junto a la cesta de trabajo.","Siempre que el peso sea inferior al propio peso corporal.","Sólo si el fabricante y el equipo permiten expresamente este uso especial.","Simplemente coloque un gancho en la barandilla y levante el material.","Las plataformas de trabajo aéreas no están diseñadas automáticamente para trabajos con grúas o cargas colgantes adicionales."],"h2-arbeitsvorbereitung":["¿Qué implica prepararse para una nueva ubicación?","Aún no conoces el sitio de construcción.","Simplemente calcule la distancia hasta el estacionamiento más cercano.","Independientemente del entorno, extiéndalo completamente inmediatamente.","Evaluar los peligros, el suelo, las rutas de tráfico, el rescate y la idoneidad del equipo.","Una evaluación de riesgos relacionada con la ubicación es un requisito previo para unas condiciones de funcionamiento seguras."],"h2-kabelschlaufe":["Un cable de alimentación cruza el camino del escenario. ¿Qué es lo correcto?","El cable podría quedar atrapado durante el movimiento.","Despeje el camino y proteja los cables eléctricos de daños.","Utilice el cable con las ruedas como umbral de la carretera.","Levante la canasta sin revisar el área del piso.","Los cables aplastados o aplastados pueden provocar riesgos eléctricos y mecánicos."],"h2-leitungsnaehe":["¿Quién aclara las medidas de protección en un sistema eléctrico?","La plataforma debe funcionar cerca de equipos activos.","La persona en la canasta decide únicamente a simple vista.","Involucrar a las autoridades responsables e implementar medidas de protección coordinadas.","La distancia sólo se determinará una vez iniciado el trabajo.","Trabajar cerca de sistemas eléctricos requiere medidas de protección planificadas y coordinadas."],"h2-funkkommunikation":["¿Por qué las señales entre el suelo y la canasta tienen que ser claras?","Una persona en el suelo ayuda en las maniobras.","Para que varias personas puedan dar instrucciones contradictorias al mismo tiempo.","Para poder probar el descenso de emergencia sin instrucciones.","Para que los movimientos sólo se realicen tras una comunicación clara.","Una comunicación clara reduce los movimientos incorrectos y las colisiones al maniobrar."],"h2-neuebedienung":["Cambias a un tipo diferente de escenario. ¿Qué se requiere?","Las funciones operativas difieren significativamente.","Instrucciones específicas del dispositivo antes del uso independiente.","Simplemente leyendo el logo de la empresa en el dispositivo.","Una prueba de manejo con la cesta ya extendida sin instrucciones.","La calificación por sí sola no reemplaza la instrucción en el tipo de dispositivo específico."],"h2-steckanschluss":["¿Qué debes comprobar antes de conectar un cargador?","Es necesario cargar una plataforma aérea de trabajo eléctrica.","Utilice cualquier enchufe independientemente de su condición y fusible.","Compruebe la conexión adecuada y el cable en buen estado según las instrucciones del fabricante.","Desenchufe el enchufe regularmente durante la carga.","Las conexiones eléctricas adecuadas e intactas protegen contra descargas eléctricas e incendios."],"h2-absperrpersonal":["Una persona entra en la zona acordonada durante los trabajos de elevación. ¿Qué estás haciendo?","Puedes ver a una persona directamente debajo de la cesta de trabajo.","Continúe conduciendo si la persona lleva casco protector.","Suelte una herramienta en su dirección como señal de advertencia.","Detenga los movimientos peligrosos y despeje el área.","Una barrera no sustituye la observación de la zona de peligro durante el funcionamiento."],"k2-arbeitsplanung":["¿Qué se debe incluir en la preparación del trabajo antes de una operación de grúa?","Aún no se han coordinado la carga, la ubicación y la ruta de transporte.","Levante primero la carga más pesada sin más planificación.","Marque la ruta más corta únicamente en el suelo del pasillo.","Aclare de antemano la capacidad de carga, las eslingas, la ruta de carga y la zona de peligro.","Un movimiento de grúa planificado requiere una manipulación de carga adecuada, rutas seguras y medidas de protección coordinadas."],"k2-hakenposition":["¿Cómo se coloca el gancho de la grúa sobre la carga antes de levantarla?","Los puntos de fijación se encuentran debajo de la grúa.","Lo más verticalmente posible por encima del centro de gravedad según el tope.","Deslícela hacia un lado para que la carga oscile más rápidamente.","En cualquier caso en el borde exterior de la carga, independientemente del centro de gravedad.","La aplicación vertical de fuerza y ​​los puntos de anclaje adecuados reducen los movimientos laterales y los movimientos incontrolados."],"k2-hakengabel":["Un gancho de carga muestra una deformación notable. ¿Qué se aplica?","El gancho parece doblado respecto de su estado habitual.","Doble la deformación hacia atrás con la siguiente carga.","Detenga el funcionamiento de la grúa y haga que un experto revise el gancho.","Coloque únicamente cargas ligeras y continúe trabajando.","La deformación puede afectar la seguridad del gancho; No se permite un uso posterior no autorizado."],"k2-zugueberlast":["La carga es más pesada de lo que se suponía inicialmente. ¿Qué estás haciendo?","Durante la preparación surge nueva información sobre el peso.","Reemplace la reserva de seguridad con un levantamiento más rápido.","Ignore el peso de la carga fijándola a otro punto.","Determine la carga real y vuelva a verificar los límites de carga.","Una elevación segura requiere datos de carga fiables y el cumplimiento de todas las capacidades de carga relevantes."],"k2-arbeitskorb":["¿Puede un gancho de grúa normal transportar personas fácilmente?","Una persona quiere llegar a un lugar de trabajo elevado.","No, el transporte de pasajeros requiere instalaciones y medidas especiales permitidas.","Sí, si la persona se agarra de la cuerda del cabestrillo.","Sí, siempre que el movimiento se realice de forma especialmente lenta.","El transporte de personas sólo está permitido en condiciones especiales previstas al efecto."],"k2-bruecke":["Un puente grúa se desplaza por un pasillo compartido. ¿Qué es importante?","Los empleados permanecen bajo la ruta de transporte.","Conduzca con la carga justo por encima de las cabezas de los empleados.","Mantenga efectivamente la ruta de carga y el área de tráfico claras y seguras.","Utilice únicamente la bocina de advertencia en lugar de tomar otras medidas.","Las personas en riesgo no deben encontrarse debajo de cargas suspendidas ni en el camino de transporte."],"k2-zweitekrane":["Dos grúas trabajan en una zona superpuesta. ¿Qué es necesario?","Los brazos o las cargas podrían chocar entre sí.","Ambos operadores de grúa trabajan al mismo tiempo sin acuerdo previo.","Los movimientos se aceleran deliberadamente para evitar intersecciones.","Coordinar las operaciones y tomar las medidas adecuadas para prevenir amenazas mutuas.","La superposición de áreas de trabajo requiere una organización operativa coordinada y salvaguardias adecuadas."],"k2-pruefbuch":["¿Cuál es la importancia de la inspección periódica obligatoria de la grúa?","La máquina se utiliza regularmente en operaciones.","Complementa el control operativo con el peritaje prescrito.","Reemplaza permanentemente cualquier inspección visual antes de comenzar el trabajo.","Sólo es necesario después de un accidente.","Las inspecciones recurrentes y los controles operativos continuos tienen diferentes tareas."],"k2-absetzflaeche":["El área de colocación prevista es desigual. ¿Cómo actúas?","La carga podría volcar al colocarla.","Coloque la carga en una esquina y déjela colgar sin cambios.","Prepare bases o superficies adecuadas, resistentes y estables.","Coloque a una persona debajo de la carga mientras la baja.","Las zonas de colocación deben soportar la carga de forma segura y evitar movimientos peligrosos de vuelco o balanceo."],"k2-anfahrbereich":["Antes de que la grúa comience a moverse, hay una persona en la zona de desplazamiento. ¿Qué estás haciendo?","La ruta está bloqueada por una persona.","Empuje a la persona a un lado con una breve prueba de manejo.","Arranque utilizando únicamente el interruptor de límite sin inspección visual.","Inicie el movimiento únicamente cuando la zona de peligro esté despejada y segura.","Los movimientos de conducción y giro no deben poner en peligro a las personas."],"k2-schlaffseil":["¿Por qué el cable de elevación no debería aflojarse incontrolablemente al bajarlo?","La carga está puesta y el gancho baja aún más.","Para que la cuerda y los ganchos no se atasquen ni se sometan a cargas incontroladas.","De modo que la carga pueda ser arrastrada lateralmente por la cuerda.","Para que las eslingas se despeguen solas del gancho.","El tendido incontrolado de cables puede provocar enredos y movimientos peligrosos de la carga."],"k2-pendel":["Una carga transportada comienza a balancearse. ¿Qué es lo correcto?","La carga se mueve lateralmente más de lo previsto.","Compensa con contramovimientos rápidos y a toda velocidad.","Reduce los movimientos de forma controlada y tranquiliza los desplazamientos sin personas en la zona de peligro.","Sostenga la carga oscilante con las manos desnudas.","Las cargas oscilantes pueden afectar a personas e instalaciones; Los movimientos tranquilos reducen el riesgo."],"k2-funkakku":["El radiocontrol de una grúa tiene la batería baja. ¿Qué se aplica?","La conexión podría romperse durante el levantamiento.","Levante una carga rápidamente antes de que falle el control.","Si se pierde la conexión, mueva la carga tirando de la eslinga.","Asegúrese de una conexión de control confiable antes de su uso.","Un control y una comunicación fiables son requisitos previos para los movimientos controlados de la grúa."],"k2-mehrereanschlaeger":["Dos personas dan señales diferentes al operador de la grúa al mismo tiempo. ¿Qué es lo correcto?","Los signos se contradicen.","Interrumpir el movimiento y aclarar la responsabilidad.","Prefiere el signo de la persona más alejada.","Continúe el movimiento según su propio sentimiento.","Los conductores de grúas necesitan una comunicación clara e inequívoca, especialmente cuando las rutas de carga son confusas."],"k2-endabschaltung":["¿Por qué no debería utilizarse incorrectamente un interruptor de límite como limitación de carrera normal?","La carga a menudo se mueve hasta la distancia máxima de elevación.","Los interruptores de límite generalmente permiten un levantamiento más rápido sin visibilidad.","Los interruptores de límite son dispositivos de seguridad y no reemplazan la operación controlada.","Deben ser golpeados lo más fuerte posible con cada golpe.","Los dispositivos de seguridad sirven para proteger contra peligros y no deben usarse en exceso según lo previsto."],"k2-wetterbeobachtung":["El viento aumenta significativamente con una gran superficie de carga. ¿Qué se requiere?","Una gran superficie de componentes actúa como una vela.","Eleve siempre la carga más para que el viento tenga menos efecto.","Reemplace las eslingas por otras más delgadas.","Evalúe los límites operativos y de viento y ajuste el levantamiento si es necesario.","El viento puede generar importantes fuerzas adicionales y movimientos pendulares, especialmente con cargas de gran superficie."],"k2-ortswechsel":["¿Qué es importante al trasladar una grúa móvil a una nueva ubicación?","Las condiciones del subsuelo y de soporte cambian.","Verifique la ubicación y el soporte del soporte antes de volver a levantar la carga.","Aplique la configuración de la ubicación anterior sin verificar.","Haga reajustar el soporte durante el levantamiento.","Cada ubicación de instalación puede tener diferentes condiciones de carga del suelo y de soporte."],"k2-betriebsbereich":["Se supone que una grúa debe trabajar al otro lado de una calle. ¿Qué hay que aclarar?","Podrían entrar terceros en la zona de peligro.","Asegure la carretera únicamente con una bocina de advertencia.","Se requieren cierres, votación y medidas de protección frente al centro.","Eleve la carga sobre los vehículos lo más rápido posible sin asegurarla.","La gestión segura del tráfico evita riesgos indebidos para terceros derivados de cargas y movimientos de grúas."],"k2-hochheben":["Después del levantamiento de prueba, una carga cuelga claramente torcida. ¿Qué es lo correcto?","Aparentemente se equivocó el enfoque.","Continúe levantando para que el desequilibrio se corrija solo.","Haga que una persona tire de la carga inclinada.","Deposite la carga de forma segura y vuelva a comprobar el accesorio y el centro de gravedad.","El elevador de prueba sirve para detectar fijaciones incorrectas y posiciones de carga inestables antes del transporte."],"k2-schwebelast":["¿Se puede dejar una carga elevada colgada y desatendida?","El turno termina, pero la carga todavía está en el gancho.","No, baje la carga de forma segura y asegure la grúa correctamente.","Sí, si la grúa está bloqueada para impedir el desplazamiento.","Sí, siempre que haya una señal de advertencia en el suelo.","En principio, las cargas suspendidas no deben dejarse desatendidas."],"k2-mitnahme":["Un colega quiere viajar sobre una carga de grúa. ¿Qué se aplica?","La carga debe transportarse a un punto más alto.","Se permite montar a caballo si el compañero lleva casco.","No está permitido transportar personas sobre cargas normales ni sujetarlas a ellas.","El viaje siempre está permitido siempre que el conductor de la grúa conozca al colega.","El transporte de personas junto con cargas genera importantes riesgos de caídas y aplastamientos."],"k2-warnsignal":["Falla un sistema de alerta operativo en la grúa. ¿Qué es lo correcto?","Ya no es posible avisar antes de iniciar la marcha.","Ignore el sistema cuando el motor esté en marcha.","Reemplace permanentemente la advertencia golpeando la carcasa.","Notifique un fallo relevante para la seguridad e interrumpa el funcionamiento según las instrucciones.","Los dispositivos de advertencia requeridos deben estar funcionales para que las personas estén protegidas de manera oportuna."],"k2-schneekante":["Una grúa móvil debe apoyarse sobre un terreno helado e irregular. ¿Qué se aplica?","El suelo puede perder su capacidad de carga al descongelarse.","Evalúe la capacidad de carga y la situación de soporte en condiciones reales.","El suelo helado siempre tiene alguna capacidad de carga.","Coloque soportes únicamente sobre piedras pequeñas.","La temperatura, la humedad y la estructura del subsuelo influyen en la capacidad de carga de los lugares donde se encuentran las grúas."],"k2-laufkatze":["Un carro avanza hacia un obstáculo. ¿Cómo actúas?","Hay un objeto en el área de conducción.","Empuje lentamente el objeto junto con la carga.","Detenga el movimiento a tiempo y elimine el obstáculo de forma segura.","Pasa el obstáculo a mayor velocidad.","Los movimientos de la grúa deben guiarse de tal manera que no se produzcan colisiones con obstáculos."],"k2-anschlagaufnahme":["Debe recoger la carga utilizando un ojal no designado. ¿Qué es lo correcto?","El ojal sólo podría estar destinado al montaje de una cubierta.","Cada ojal es adecuado para carga completa de grúa.","Cargue el ojal únicamente con dos personas al mismo tiempo.","Verificar la capacidad de carga y la idoneidad del punto de anclaje antes de su uso.","No todos los ojales existentes son un punto de fijación estable para cargas de grúa."],"l2-seilbruch":["Un cable metálico muestra varios alambres individuales rotos. ¿Qué es lo correcto?","Los puntos de rotura se encuentran en la zona del cable portante.","No continúe utilizando equipos de elevación y hágalo evaluar por un profesional.","Doble los extremos del cable hacia atrás con las manos desnudas.","Continúe usando la cuerda si la carga es particularmente ligera.","Las roturas de cables pueden ser un criterio de descarte; Las cuerdas dañadas deben ser evaluadas profesionalmente."],"l2-schaekel":["¿Qué es crucial al usar un grillete?","Un grillete conecta la eslinga y la carga.","Reemplace el perno con cualquier clavo.","Verifique que la capacidad de carga sea adecuada, que no haya daños y que los pernos sean correctos.","Estima la capacidad de carga según el color.","Los grilletes deben tener el tamaño adecuado, utilizarse en su totalidad y en la dirección de carga prevista."],"l2-tragfaehigkeit":["¿Qué hay que tener en cuenta al utilizar varios hilos?","Los hilos discurren en ángulo con la vertical.","Simplemente sume la capacidad de carga de cada hilo como desee.","Cuelga la carga únicamente en el hilo más ligero.","Tenga en cuenta la capacidad de carga de todo el tipo de anclaje y ángulo.","El ángulo de inclinación y el número efectivo de cordones influyen decisivamente en la carga admisible."],"l2-schweissnaht":["¿Se puede soldar un punto de anclaje improvisado a una carga?","No existen puntos de recogida adecuados y designados para la carga.","Utilice únicamente puntos de anclaje debidamente diseñados y aprobados.","Cualquier cordón de soldadura es suficiente sin necesidad de realizar pruebas.","Inserte un gancho a través de una abertura en la chapa.","Se debe demostrar que los puntos de anclaje son adecuados para las fuerzas involucradas en la elevación."],"l2-einseitig":["Una carga es mucho más pesada por un lado. ¿Cómo lo haces?","El centro de gravedad se encuentra fuera del centro geométrico.","Deje todos los mechones del mismo largo independientemente del centro de gravedad.","Determine el centro de gravedad y ajuste la posición en consecuencia.","Primero levante la carga a la altura máxima de elevación.","Si el centro de gravedad está descentrado, las cargas pueden inclinarse inesperadamente o los hilos individuales pueden sobrecargarse."],"l2-kettenriss":["¿Qué se aplica a una eslinga de cadena con grietas visibles?","Hay una grieta en uno de los eslabones de la cadena.","Marque la grieta con pintura y levántela sin cambios.","Envuelva el enlace con alambre y reutilícelo.","Retire la cadena inmediatamente e informe a la persona responsable.","Las grietas en los eslabones de las cadenas portantes son daños relevantes para la seguridad y requieren una puesta fuera de servicio."],"l2-lastfuehrung":["¿Cómo se transporta una carga grande cuando existe riesgo de rotación?","La carga puede oscilar lateralmente durante la elevación.","Utilice dispositivos de guiado adecuados y una distancia de seguridad.","Sostenga la carga directamente entre sus manos mientras conduce.","Póngase debajo de la carga y alinéela desde abajo.","El guiado de la carga no debe provocar que las manos o el cuerpo entren en la zona de peligro."],"l2-schnueren":["¿Qué es importante a la hora de colocar los cordones?","La eslinga se guía alrededor de un componente.","Asume la misma capacidad de carga que cualquier otro tipo de anclaje.","Observe la idoneidad del tipo de fijación y la carga permitida según la marca.","Junte la eslinga en cualquier medida sin comprobarlo.","El tipo de accesorio para cordones puede cambiar la capacidad de carga permitida y debe usarse correctamente."],"l2-winkelmesser":["¿Por qué no puedes ignorar un ángulo de hebra plana?","Dos líneas de eslinga discurren casi horizontalmente respecto a la carga.","Un ángulo plano automáticamente fortalece el hilo.","La carga siempre se distribuye uniformemente independientemente del ángulo.","Las fuerzas elevadas sobre los cordones pueden superar la capacidad de carga permitida.","A medida que aumenta el ángulo con la vertical, aumentan las tensiones sobre los hilos."],"l2-heisse-last":["¿Qué necesitas para comprobar si hay una carga caliente?","Una pieza de acero fue tratada térmicamente recientemente.","Observe los límites de temperatura de las eslingas y seleccione la adecuada.","Cada eslinga textil puede soportar cualquier temperatura.","El etiquetado no importa cuando hace calor.","La temperatura puede afectar la capacidad de carga permitida de las eslingas."],"l2-abstand":["¿Puedes poner los dedos debajo de la carga al colocarla?","La carga debe aterrizar sobre una superficie con precisión milimétrica.","Sí, si usas guantes de trabajo.","No, mantén la distancia y utiliza ayudas adecuadas.","Sí, si el movimiento de la grúa es especialmente lento.","Partes del cuerpo entre la carga y la base pueden quedar atrapadas."],"l2-verbindung":["Un eslabón de conexión de la cadena de la eslinga no está bloqueado. ¿Qué se aplica?","Falta el sujetador.","Utilice el cerrojo sin cerradura cuando nadie esté mirando.","Sellar el elemento con cinta adhesiva.","No golpee hasta que el sujetador esté correctamente asegurado.","Los elementos de conexión deben fijarse completamente y según su diseño."],"l2-lasthaken":["¿Qué se comprueba cuando se cuelga del gancho de una grúa?","Se deben introducir varias eslingas en el gancho.","Garantizar un ajuste seguro y la idoneidad de los ganchos y la suspensión.","Coloque eslingas en la punta del anzuelo.","Reemplace el bloqueo del gancho con una brida para cables.","La fuerza debe aplicarse según lo previsto en las áreas designadas."],"l2-fasern":["Una correa de elevación muestra graves rugosidades y daños en las fibras. ¿Qué es lo correcto?","Las fibras de soporte están visiblemente dañadas.","Cubre el daño con otro nudo.","Separar la correa de elevación y hacerla revisar por un especialista.","Luego levante la carga más rápidamente.","Las fibras de soporte dañadas pueden reducir significativamente la capacidad de carga de una correa de elevación."],"l2-anheben":["¿Qué se aplica inmediatamente después del primer centímetro de elevación?","La carga apenas se está levantando de su base.","Tire la carga hasta su altura máxima sin control.","Compruebe bajo la carga si las eslingas están tensas.","Comprobar la posición de la parada, el equilibrio y el comportamiento del movimiento.","Un levantamiento de prueba controlado hace visibles las posibles inestabilidades antes del transporte posterior."],"l2-lastgewichte":["Se desconoce el peso de la carga. ¿Qué es lo correcto?","El componente no tiene ninguna marca de peso.","Determine el peso que se puede cargar antes de seleccionar las eslingas.","Calcule el peso según el color de la carga.","Utilice cualquier cabestrillo de doble longitud.","Sin un peso conocido o determinado de forma fiable, no se puede comprobar con seguridad la idoneidad de las eslingas."],"l2-lose-teile":["Hay herramientas sueltas sobre la carga a levantar. ¿Qué estás haciendo?","Las herramientas podrían caerse al levantarlas.","Sostenga las herramientas con una mano mientras conduce.","Retire o asegure efectivamente los objetos sueltos antes de levantarlos.","Eleve la carga un poco más rápido para que nada resbale.","Pueden caer objetos sueltos y poner en peligro a las personas que se encuentren en la zona."],"l2-wind":["Cuando hay vientos fuertes, se coloca una carga grande. ¿Qué se aplica?","El componente ofrece al viento una gran superficie para atacar.","Elevar la carga sin considerar movimientos de balanceo.","Otras personas deberían sujetar la carga directamente.","Evaluar las condiciones del viento y abstenerse de levantar objetos si la situación no es segura.","Las fuerzas del viento pueden afectar la guía de la carga y la estabilidad durante el transporte."],"l2-unterlage":["¿Por qué es importante la documentación adecuada al destetar?","Una carga redonda rodaría por el suelo.","Coloque la carga firmemente sobre el suelo y, si es necesario, asegúrela para que no se desplace.","Dejar la carga directamente sobre las eslingas.","Empuje los documentos bajo la carga sólo después de haberlos depositado.","Los soportes adecuados evitan vuelcos y movimientos no deseados al sentarse."],"l2-transportweg":["¿Qué hay que coordinar antes de transportar la carga?","La carga se mueve sobre varias áreas de trabajo.","Sólo la duración esperada del centro.","Ruta de carga segura, comunicación y barreras necesarias.","Una persona debe mostrar el camino bajo la carga.","El transporte de cargas requiere vías de circulación seguras y una coordinación clara."],"l2-schutzschlauch":["¿A qué se debe prestar atención al utilizar eslingas con manguera protectora?","Una banda se apoya contra un borde rugoso.","Cualquier paño fino sustituye a una protección de bordes adecuada.","Una manguera protectora elimina cualquier límite de carga permitido.","Seleccionar el equipo de protección según idoneidad y requisitos de aplicación.","El equipo de protección debe coincidir con el material, el borde y la carga prevista."],"l2-reinigung":["Una correa de elevación estaba contaminada con una sustancia química desconocida. ¿Qué es lo correcto?","La cinta ya no se puede evaluar claramente.","Dejar de usar y aclarar la compatibilidad o condición profesionalmente.","Limpiar con cualquier solvente y continuar levantando inmediatamente.","Ignore el químico mientras la cinta esté seca.","Los productos químicos pueden afectar la resistencia de las eslingas textiles."],"l2-aufhaengung":["¿Qué verifica si hay varios hilos en el eslabón de suspensión?","Se colocan dos hebras juntas en una suspensión.","Un hilo puede moverse hacia la punta del anzuelo a voluntad.","Todos los elementos de conexión deben ser adecuados y estar dispuestos según lo previsto.","Para cargas pequeñas se puede utilizar un anillo con una grieta.","Los elementos de tope y de conexión deben ser portantes y estar correctamente dispuestos."],"l2-einweiserrolle":["¿Qué ocurre si el atacante y el operador de la grúa no tienen línea de visión?","Un transportista bloquea la vista del punto de entrega.","Coordinar llamando a varias personas sin responsabilidad.","Mueva la carga basándose en el ruido sin instrucciones.","Organice una comunicación clara y segura y deténgala si no está clara.","La falta de visibilidad debe compensarse con una coordinación eficaz y una comunicación segura."],"l2-ausserbetrieb":["Se solucionó un cabestrillo dañado. ¿Qué más es importante?","Sigue siendo de libre acceso junto con los recursos listos para usar.","Protéjalo contra un uso accidental posterior e informe a la persona responsable.","Devuelva el producto sin marcar al inventario.","Utilícelo de nuevo únicamente cuando transporte una carga especialmente ligera.","Las eslingas desechadas deben protegerse de forma fiable antes de su uso posterior."],"b2-schwenkradius":["¿Por qué es fundamental el radio de giro trasero de una excavadora?","La cola se mueve sobre un área de trabajo limitada.","Los terceros pueden quedar atrapados en la superestructura oscilante.","El radio de giro no influye en las personas que se encuentran junto a la máquina.","La parte trasera siempre se mueve sólo en el sentido de la marcha.","Al girar, también aparece una zona de peligro detrás de la máquina."],"b2-verkehrseinweiser":["¿Cómo se asegura la conducción cuando la visibilidad está limitada?","Una excavadora tiene que maniobrar detrás de un obstáculo.","Conducir sin ver las señales del señalizador.","Si es necesario, organice una instrucción adecuada con una comunicación clara.","Asegure la marcha atrás solo tocando la bocina una vez.","Las rutas confusas requieren medidas efectivas para evitar colisiones y atrapamientos."],"b2-standplatz":["¿Qué se aplica a un soporte de excavadora en una pendiente?","El suelo está inclinado y puede resultar resbaladizo.","La máquina puede extenderse tanto como quiera en cualquier inclinación.","Coloque siempre la excavadora sobre una capa de tierra suelta.","Verifique la estabilidad y los límites de funcionamiento de la máquina antes de su uso.","La pendiente y el subsuelo tienen una influencia significativa en la estabilidad."],"b2-oberleitung":["¿Por qué es necesario planificar la distancia entre la barrera y las líneas eléctricas?","El brazo puede acercarse al cable al girar.","También es posible una descarga eléctrica sin contacto directo.","Sólo el cubo puede conducir electricidad, no la pluma.","Con suelo seco, cada distancia es automáticamente segura.","Se deben aclarar los límites de uso y las distancias de protección antes de acercarse a los sistemas eléctricos."],"b2-fremdperson":["Un transeúnte entra en la zona de obras en la zona de panorámica. ¿Qué es lo correcto?","De repente, la persona se encuentra cerca de la cuchara de la excavadora.","Levante la pala y colóquela sobre la persona.","Detenga el movimiento inmediatamente y despeje el área.","Simplemente continúa observando a la persona desde la ventana lateral.","Las personas que se encuentren en la zona de peligro no deben correr peligro debido a los movimientos laborales."],"b2-parkstellung":["¿Cómo se asegura una máquina de movimiento de tierras una vez finalizado el trabajo?","La excavadora permanece desatendida en la obra.","Deje la cuchara a la altura de la cabeza.","Deje que el motor funcione sin supervisión.","Depositar el equipo de trabajo, asegurar la máquina y evitar su uso no autorizado.","El estacionamiento adecuado reduce el movimiento accidental y el acceso no autorizado."],"b2-eigenlast":["¿Por qué son cruciales los límites del equipo al levantar con una excavadora?","Se va a levantar una carga pesada sobre la pluma.","De lo contrario se podría superar la estabilidad y la capacidad de carga permitida.","Cualquier máquina puede levantar cualquier carga siempre que quepa el cucharón.","Sólo la longitud de la cuerda de la eslinga determina el riesgo.","La información sobre la capacidad de elevación y carga depende del equipo y la situación de la aplicación."],"b2-untergrundhohlraum":["El suelo sobre un sótano antiguo podría estar hueco. ¿Qué estás haciendo?","Debes conducir la excavadora hasta el área.","Cruza el lugar con el máximo impulso.","Aclarar la capacidad de carga y posibles cavidades antes de continuar.","Simplemente coloque una carga pesada en la superficie.","Las cavidades pueden colapsar bajo el peso de la máquina y provocar que ésta se estrelle."],"b2-feuchtigkeit":["Después de fuertes lluvias, el terraplén se vuelve blando. ¿Qué es lo correcto?","Una excavadora trabaja cerca del borde del terraplén.","Acerque la máquina al borde para aumentar el alcance.","Ignore los cambios hasta el final del turno.","Reevaluar las condiciones del suelo y de estabilidad.","La penetración de humedad puede cambiar la capacidad de carga y la estabilidad de los terraplenes."],"b2-bodenprobe":["¿Por qué es necesario comprobar los planos de las tuberías antes de la excavación?","Los cables podrían pasar por debajo de la excavación prevista.","Para poder identificar líneas y planificar medidas de seguridad adecuadas.","Para que la excavación se pueda realizar más rápidamente, independientemente de sistemas de terceros.","Porque las máquinas nunca deben utilizarse cerca de cables.","Las líneas de suministro subterráneas requieren una aclaración fiable de su ubicación antes de los trabajos de excavación."],"b2-maschinenzugang":["¿Qué se aplica al entrar y salir de la máquina de movimiento de tierras?","La máquina se encuentra en un terreno irregular.","Deslice hacia abajo la línea hidráulica para sacarla de la cabina.","Utilice los escalones designados y asegúrese de estar en una posición segura.","Salta sobre el brazo giratorio mientras la máquina está en funcionamiento.","Las subidas seguras y los puntos de parada adecuados reducen el riesgo de caídas y aplastamientos."],"b2-kupplung":["¿Cómo se revisa una retroexcavadora nueva después de la instalación?","La cuchara se conecta mediante el acoplamiento rápido.","Juzgue la cuchara sólo visualmente desde una distancia mayor.","Páse directamente debajo de la cuchara levantada.","Asegúrese de que el bloqueo sea correcto y de los pasos de control prescritos.","Los archivos adjuntos mal bloqueados pueden soltarse y poner en peligro a las personas."],"b2-hydraulikwartung":["¿Por qué no se permite abrir las líneas hidráulicas bajo presión?","Es necesario reemplazar una manguera.","El líquido que se escapa puede provocar lesiones graves debido a la alta presión.","La presión siempre impide que el aceite se escape.","Una línea abierta se puede comprobar de forma segura con las manos.","El fluido a alta presión puede penetrar el tejido y requiere un alivio de presión seguro."],"b2-fahrweg":["Tienes que pasar por un puente de construcción temporal. ¿Qué estás comprobando?","El puente sólo está diseñado para determinadas cargas.","Si el color del puente coincide con el de la máquina.","Capacidad de carga y adecuación al peso y dimensiones de la máquina.","Sólo si ya ha pasado un coche ligero por el puente.","Las estructuras provisionales sólo podrán utilizarse dentro de su capacidad de carga demostrada."],"b2-baggertransport":["¿Qué es importante al transportar una excavadora con plataforma rebajada?","La máquina se lleva a la siguiente obra.","Deje que el equipo de trabajo sobresalga sin apretar del borde.","Mantenga la puerta de la cabina abierta mientras conduce.","Asegure la máquina según las especificaciones de transporte y controle el equipo de carga.","Los candados de transporte y los dispositivos de carga adecuados evitan resbalones y caídas."],"b2-schaufelfuellung":["¿Por qué no se permite que una cargadora de ruedas avance rápido con el cucharón elevado?","La carga es pesada y el suelo es irregular.","Un centro de gravedad alto puede aumentar el riesgo de vuelco y problemas de visibilidad.","La cuchara se estabiliza automáticamente a altas velocidades.","La altura de la pala es irrelevante para la estabilidad.","Un centro de gravedad elevado suele empeorar la estabilidad al conducir y tomar curvas."],"b2-fussgaenger":["¿Cómo te comportas al maniobrar junto a peatones?","El acceso a la obra es también un sendero.","Utilice la pala para dirigir a los peatones hacia un lado.","Realice el movimiento de conducción únicamente cuando el área esté despejada y manejable de manera segura.","Simplemente toque la bocina una vez y conduzca lentamente sin visibilidad.","El tráfico de vehículos y pasajeros debe estar efectivamente separado o coordinado de manera segura."],"b2-ueberlastwarnung":["Al levantar, la máquina informa sobrecarga. ¿Qué estás haciendo?","Una carga elevada alcanza los límites permitidos.","Apague la advertencia y continúe levantándola sin cambios.","Apriete la carga repentinamente mientras la máquina está en funcionamiento.","Detener movimientos peligrosos y corregir con seguridad la situación de carga.","Las advertencias de sobrecarga indican posibles violaciones de límites y riesgos de estabilidad."],"b2-wasserleitung":["Mientras se excava, se descubre una tubería desconocida. ¿Qué se aplica?","La línea no se muestra en los planos de construcción.","Detenga el trabajo en el área afectada y haga que un profesional identifique la línea.","Intente mover la línea con la pala excavadora.","Continúe cavando directamente debajo de la línea sin verificar.","Las líneas desconocidas pueden causar peligros eléctricos, de gas o de agua."],"b2-hangefahrt":["¿Cómo se conduce una excavadora en una pendiente pronunciada?","El recorrido previsto discurre por una pendiente.","Conduzca por la pendiente independientemente de los límites del fabricante.","Observe la inclinación permitida y el estilo de conducción prescrito de la máquina.","Gire el brazo hacia afuera para equilibrar el vehículo.","La pendiente permitida depende de la máquina, del terreno y de las indicaciones del fabricante."],"b2-schlechtebeleuchtung":["Cuando se trabaja en un foso oscuro, la visibilidad es inadecuada. ¿Qué es lo correcto?","Apenas se ven personas y obstáculos.","Aumente la velocidad de excavación para completar la operación rápidamente.","No utilice las luces mientras el motor esté en marcha.","Deje de trabajar hasta que las zonas de peligro sean suficientemente visibles.","Para los movimientos controlados de la máquina se requiere una visibilidad segura de las áreas de conducción y de trabajo."],"b2-kettenverschleiss":["Durante el control diario se observa una oruga dañada. ¿Qué estás haciendo?","Una conexión de cadena muestra daños claros.","No continuar utilizando la máquina sin control y reportar cualquier daño.","Continúe conduciendo a alta velocidad para que la cadena se enderece.","Continúe trabajando únicamente en terrenos blandos sin comprobarlo.","Los daños en la unidad pueden afectar la capacidad de control y la estabilidad."],"b2-ladearbeiten":["Cargas un camión con la excavadora. ¿Qué es importante?","El conductor del camión permanece cerca de la zona de carga.","Gire el cucharón sobre la cabina del conductor desprotegida.","Evitar que las personas permanezcan en la zona de peligro y coordinar procesos.","Comience a cargar sin comunicarse con el conductor.","Durante la carga existe peligro por caída de material y movimientos oscilantes."],"b2-arbeitsunterbrechung":["Interrumpes los trabajos de excavación para una reunión. ¿Qué se aplica?","La máquina debe permanecer varios minutos sin ser utilizada.","Deja la pala levantada como marcador.","Deje la máquina desatendida con la transmisión de tracción engranada.","Deposite la máquina de forma segura y asegure la máquina contra un uso involuntario.","Incluso las interrupciones breves requieren un estado seguro de la máquina."],"b2-rollmaterial":["El material suelto puede caer durante el transporte con la cargadora de ruedas. ¿Qué es lo correcto?","El cargador se acerca a los empleados.","Recoja la carga de forma segura y elija un estilo de conducción seguro con una posición de pala adecuada.","Levante la pala lo más alto posible para que el área circundante tenga una vista clara.","Recoger la carga sin limitar el llenado del cubo.","Las cargas sueltas, las posiciones altas del cucharón y la mala visibilidad pueden poner en peligro a las personas y al tráfico."]};
